M.EVENT_STRIKE = "strike"   -- lib/ability_channel kind: { target = {x, y, z}, from = {x, y} } at the `smoke` marker

local function bad(v) return type(v) ~= "number" or v ~= v or v == math.huge or v == -math.huge end

-- Whether the server takes a `strike` event. `facts` is the server's own: held_ms (its World steps since the run's start), from
-- {x, y, z} (its copy of the player's middle), aim {x, y, z} or nil, facing {x, y}. Returns true, or false and why.
function M.check_strike(T, ev, facts)
  local t, f = ev.target, ev.from
  if type(t) ~= "table" or type(f) ~= "table" or bad(t.x) or bad(t.y) or bad(t.z) or bad(f.x) or bad(f.y) then
    return false, "malformed"
  end
  if facts.held_ms < T.smoke_ms - T.strike_early_ms then
    return false, ("too early (%d ms into the run)"):format(facts.held_ms)
  end
  local p = facts.from
  local fx, fy = f.x - p.x, f.y - p.y
  local fd = math.sqrt(fx * fx + fy * fy)
  if fd > T.strike_from_slack then return false, ("from %.1f blocks off the player"):format(fd) end
  local dx, dy, dz = t.x - p.x, t.y - p.y, t.z - p.z
  local d3 = math.sqrt(dx * dx + dy * dy + dz * dz)
  local reach = T.target_cap + T.strike_range_slack
  if d3 > reach then return false, ("target %.1f blocks away, over %.1f"):format(d3, reach) end
  local d = math.sqrt(dx * dx + dy * dy)
  if d >= T.strike_cone_min then
    local ux, uy
    if facts.aim then ux, uy = facts.aim.x - p.x, facts.aim.y - p.y end
    if not ux or ux * ux + uy * uy < T.strike_cone_min * T.strike_cone_min then ux, uy = facts.facing.x, facts.facing.y end
    local u = math.sqrt(ux * ux + uy * uy)
    if u > 0 then
      local cos = (dx * ux + dy * uy) / (d * u)
      if cos > 1 then cos = 1 elseif cos < -1 then cos = -1 end
      local deg = math.deg(math.acos(cos))
      if deg > T.strike_cone_deg then
        return false, ("target %.0f degrees off the aim, over %.0f"):format(deg, T.strike_cone_deg)
      end
    end
  end
  return true
end

-- How many clones are due by `held_ms` into the run (the `clone` markers as tuning's clone_ms), given `started` already.
function M.clones_due(T, started, held_ms)
  local n = 0
  for i = started + 1, #T.clone_ms do
    if held_ms >= T.clone_ms[i] then n = n + 1 else break end
  end
  return n
end

-- The damage of one strike, from the attacker's damage stat.
function M.damage(T, stat) return stat * T.damage_mult end

-- The smoke: starts at the `smoke` marker; returns how many bursts are due after `dt` more ms at ability time `ability_ms` (one at
-- once, then one each smoke_every_ms, none after smoke_end_ms).
function M.smoke_due(T, cast, dt, ability_ms)
  if not cast.smoke_age then return 0 end
  cast.smoke_age = cast.smoke_age + dt
  if ability_ms > T.smoke_end_ms then return 0 end
  local want = math.floor(cast.smoke_age / T.smoke_every_ms) + 1
  local due = want - cast.smoke_done
  if due < 0 then due = 0 end
  cast.smoke_done = cast.smoke_done + due
  return due
end

function M.start_smoke(cast)
  if cast.smoke_age then return end
  cast.smoke_age, cast.smoke_done = 0, 0
end

-- ---- the particles ---------------------------------------------------------------------------------------------------------

-- The names of the particle kinds (tuning `particles`), sorted, so the rules are set in one order.
function M.particle_kinds(T)
  local names = {}
  for name in pairs(T.particles) do names[#names + 1] = name end
  table.sort(names)
  return names
end

-- lib/fx's rule for the particle kind `name`: a short life cut at random, shrinking with its age, slowed and pushed up.
function M.particle_rule(T, name)
  local k = T.particles[name]
  return { scale = k.scale, life_ms = k.life_ms, life_jitter = k.life_jitter, shrink = true, levels = k.levels, drag = k.drag,
    rise = k.rise }
end

-- The lib/fx.scatter calls of one list of tuning (`smoke`, `puff`, `puff_end`, `wisp`) round the bottom point `at` {x, y, z} of a
-- body `height` blocks tall that moves at `vel` {x, y} blocks a second (nil: still): a list of { def, centre, count, radius, height,
-- out }.
function M.spawns(T, list, at, height, vel)
  local out = {}
  for _, s in ipairs(list) do
    local k = T.particles[s.kind]
    local carry = s.carry or 0
    local vx, vy = 0, 0
    if vel then vx, vy = vel.x * carry, vel.y * carry end
    local ax, ay, az = unpack(k.accel)
    out[#out + 1] = {
      def = { type = k.type, scale = k.scale, color = k.color, spreading = k.spreading, accel = { ax + vx, ay + vy, az } },
      centre = { at.x, at.y, at.z }, count = s.count, radius = s.radius, height = s.height or height, out = s.out,
    }
  end
  return out
end

-- The aura at ability time `ms`: alpha (0 when not shown) and the turn in degrees of the outer copy (the inner one turns the other
-- way, twice as fast).
function M.ash_at(T, ms)
  if ms < T.ash_from_ms or ms >= T.ash_to_ms then return 0, 0 end
  local turn = T.ash_turn_deg * (ms - T.ash_from_ms) / (T.ash_to_ms - T.ash_from_ms)
  local a = T.ash_alpha
  if ms < T.ash_full_ms then a = a * (ms - T.ash_from_ms) / (T.ash_full_ms - T.ash_from_ms)
  elseif ms > T.ash_fade_ms then a = a * (T.ash_to_ms - ms) / (T.ash_to_ms - T.ash_fade_ms) end
  return a, turn
end

-- The skill tree's placeholders (lib/tooltip): the cooldown in seconds at `rank`, and the damage as a multiple of the stat.
M.TOOLTIP_COOLDOWN = "smashcooldown"
M.TOOLTIP_DAMAGE = "retreatdistance"

function M.tooltip_values(T, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(T, rank) / units.MS_PER_S),
    [M.TOOLTIP_DAMAGE] = ("%g"):format(T.damage_mult),
  }
end

return M
end

-- @module skills_unleashed.logic.berserker (logic/berserker.lua)
package.preload["skills_unleashed.logic.berserker"] = function(...)
-- skills_unleashed.logic.berserker: the geometry, the timeline and the damage curve of Berserker's Uppercut. Pure: no kyubu, no ffi,
-- so a unit test decides it. Every number is a field of the `berserker` block of lib/tuning.lua, passed in as `t`.
--
-- The ability in one line: the player stands still for the wind-up, hops, and at the clip's `hit` marker throws the nearest
-- enemy of a box in front into the air; the enemy flies faster than gravity would let it, and when it lands it takes the large
-- part of the damage and the enemies round the landing are hurt and thrown away.
local volume = require("skills_unleashed.lib.volume")
local units = require("skills_unleashed.lib.units")
local tuning = require("skills_unleashed.lib.tuning")

local M = {}

M.MARKER_HIT = "hit"

-- The player cannot move from the start to the end of the wind-up.
function M.holds_player(t, elapsed_ms)
  return elapsed_ms < t.windup_ms
end

-- The hop starts `hop_delay_ms` after the wind-up.
function M.hop_due(t, elapsed_ms)
  return elapsed_ms >= t.windup_ms + t.hop_delay_ms
end

-- The strike lands at `strike_ms` (on the client the clip's hit marker; the server has no clip). True once elapsed has reached it.
function M.strike_due(t, elapsed_ms)
  return elapsed_ms >= t.strike_ms
end

-- The two parts of the damage for a damage stat: (at the strike, at the landing). They add up to the total.
function M.damage(t, stat)
  local total = stat * t.damage_mult
  local at_strike = total * t.strike_fraction
  return at_strike, total - at_strike
end

-- The box in front of the player. `enemies` are creature tables (x, y, z in blocks). Returns the primary entry (the nearest
-- one, or nil) and the list of the other entries, nearest first. Entries are those of lib/volume.
function M.strike_targets(t, origin, facing, enemies)
  local inside = volume.in_box(origin, facing, enemies,
    { length = t.box_length, half_width = t.box_half_width, reach_z = t.box_reach_z })
  local primary = inside[1]
  local others = {}
  for i = 2, #inside do others[#others + 1] = inside[i] end
  return primary, others
end

-- A horizontal push of `speed` away from the origin of the entry, along `facing` when the creature is on the origin.
local function away(t, entry, facing, speed)
  local dx, dy = volume.away(entry, facing, t.away_min)
  return dx * speed, dy * speed
end

-- The velocity (blocks per second: x, y, z) of the primary right after the strike.
function M.primary_launch(t, entry, facing)
  local vx, vy = away(t, entry, facing, t.primary_push)
  return vx, vy, M.launch_speed(t)
end

-- The velocity of another target of the strike: a shove away from the player, with a little lift.
function M.secondary_shove(t, entry, facing)
  local vx, vy = away(t, entry, facing, t.secondary_push)
  return vx, vy, t.secondary_lift
end

-- The upward speed that reaches `rise_blocks` under the air gravity.
function M.launch_speed(t)
  return math.sqrt(2 * t.air_gravity * t.rise_blocks)
end

-- The vertical velocity after one World step of `dt_ms` in the air (the creature's own is overwritten each step).
function M.air_velocity(t, vz, dt_ms)
  return vz - t.air_gravity * dt_ms / units.MS_PER_S
end

-- The state of a creature in the air. `mark` = { vz (blocks per second), age_ms, left_ground }; `seen` = { present, alive,
-- grounded } from this step. Returns what the step decided:
--   "fly"     still in the air: mark.vz is the velocity to write
--   "land"    it came down: the landing goes off here
--   "died"    it died in the air: the landing goes off where it was, without it
--   "timeout" it has been in the air for max_air_ms: the landing goes off where it is
--   "gone"    it left the World (the World was left or it was removed): nothing happens
function M.fly(t, mark, dt_ms, seen)
  mark.age_ms = mark.age_ms + dt_ms
  if not seen.present then return "gone" end
  if not seen.alive then return "died" end
  if mark.age_ms > t.max_air_ms then return "timeout" end
  if not seen.grounded then mark.left_ground = true end
  if mark.left_ground and seen.grounded then return "land" end
  mark.vz = M.air_velocity(t, mark.vz, dt_ms)
  return "fly"
end

-- The radius of the landing at `rank` (below 1 reads 1): the base plus a share of the gain that grows with the rank and never
-- ends, the way the game's own abilities scale.
function M.impact_radius(t, rank)
  local steps = rank - 1
  return t.impact_radius + t.impact_radius_gain * tuning.power(steps, t.rank_scale)
end

-- Everyone within the impact radius of the landing point (`skip` is a creature table that stays out). Entries are lib/volume's.
function M.impact_targets(t, rank, origin, enemies, skip)
  return volume.in_radius(origin, enemies, { radius = M.impact_radius(t, rank), reach_z = t.impact_reach_z }, skip)
end

-- The velocity of a creature thrown away from the landing point.
function M.impact_shove(t, entry, facing)
  local vx, vy = away(t, entry, facing, t.impact_push)
  return vx, vy, t.impact_lift
end

-- The ring of a strike that connects, for lib/fx (`pos` in world units; `facing` the player's horizontal facing): its normal is
-- the direction of the blow, forward and up by strike_wave_pitch_deg, so the plane is tilted and not on the ground.
function M.strike_wave_def(t, pos, facing)
  local pitch = math.rad(t.strike_wave_pitch_deg)
  local flat = math.cos(pitch)
  local grow = t.strike_wave_radius - t.strike_wave_inner - t.strike_wave_thickness
  if grow < 0 then grow = 0 end
  return {
    pos = pos,
    facing = { facing.x * flat, facing.y * flat, math.sin(pitch) },
    inner = t.strike_wave_inner,
    thickness = t.strike_wave_thickness,
    expansion = grow / t.strike_wave_ticks,
    life_ticks = t.strike_wave_ticks,
    fade_on_tick = t.strike_wave_fade_tick,
    fade_speed = t.strike_wave_fade_speed,
    color = t.strike_wave_color,
  }
end

-- The shockwave's def for lib/fx (`pos` is passed through, in world units): a ring that reaches the impact radius at the end of
-- its life.
function M.shockwave_def(t, rank, pos)
  local radius = M.impact_radius(t, rank)
  local grow = radius - t.shockwave_inner - t.shockwave_thickness
  if grow < 0 then grow = 0 end
  return {
    pos = pos,
    inner = t.shockwave_inner,
    thickness = t.shockwave_thickness,
    expansion = grow / t.shockwave_ticks,
    life_ticks = t.shockwave_ticks,
    fade_on_tick = t.shockwave_fade_tick,
    fade_speed = t.shockwave_fade_speed,
    color = t.color,
  }
end

-- The numbers of the skill tooltip at `rank` (0 for an unlearned skill reads rank 1), as the game's text engine shows them:
-- placeholder name (the dictionary writes it with an @) to text. Same source as the ability, so the tooltip cannot disagree.
-- The names are two of the game's own placeholders (smash's cooldown, retreat's distance), used as carriers:
-- the engine did not resolve a name of the mod's own (the game showed them blank with the values in the map),
-- and the placeholder map is built again for every tooltip, so overwriting a vanilla name for skill 9 changes nothing else.
-- The damage is not shown, by design: the numbers are the cooldown and the landing's radius.
M.TOOLTIP_COOLDOWN, M.TOOLTIP_RADIUS = "smashcooldown", "retreatdistance"

function M.tooltip_values(t, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(t, rank) / units.MS_PER_S),
    [M.TOOLTIP_RADIUS] = ("%.1f"):format(M.impact_radius(t, rank)),
  }
end

return M
end

-- @module skills_unleashed.logic.fire_mage (logic/fire_mage.lua)
package.preload["skills_unleashed.logic.fire_mage"] = function(...)
-- skills_unleashed.logic.fire_mage: the life of the Fire Mage's Fire Circle, its held charge, the circle it casts and the damage the
-- circle does. Pure: no kyubu, no ffi, so a unit test decides it. Every number is a field of the `fire_mage` block of lib/tuning.lua,
-- passed in as `t`.
--
-- The ability in one line: the key held charges mana (the player walks at half speed, the hands turn over the head); on the release
-- the mage points at the aimed spot (up to a range), two points come down onto it and a circle of fire forms, wider the more mana was
-- charged, which hurts every enemy in it for a time without stunning it.
--
-- The phases of one activation:
--   idle      nothing is going on
--   charge    the key is held: the charge grows at the game's own rate, at most the mp (the script writes `charged_mp`)
--   release   the key is up: the release clip plays; at its `cast` marker the charge is spent and the circle is cast
--   done      the cast (or the fizzle) is over: the script ends the ability
--
-- The restart (see lib/tuning.lua): at the release the script writes the mode time 0 so that the release clip plays from its start; the
-- loader reads that as a new activation (an `interrupted` end, then a start). `request_restart` makes `on_ability_end` and `on_start`
-- let that pair pass; if the loader never sees it (the write failed) `step` gives the wait up after restart_wait_ms.
local tuning = require("skills_unleashed.lib.tuning")
local units = require("skills_unleashed.lib.units")

local M = {}

M.MARKER_CAST = "cast"
M.IDLE, M.CHARGE, M.RELEASE, M.DONE = "idle", "charge", "release", "done"

-- How an activation ended (what `on_ability_end` returns).
M.ENDED_CAST = "cast"                -- the circle was cast
M.ENDED_FIZZLED = "fizzled"          -- released with less than the least charge: nothing was cast or spent
M.ENDED_INTERRUPTED = "interrupted"  -- stunned, killed, or otherwise cut off before the cast
M.ENDED_DIED = "died"                -- the player died or left

-- What `step` returns.
M.EVENT_RELEASE, M.EVENT_FIZZLE, M.EVENT_CAST, M.EVENT_FINISH = "release", "fizzle", "cast", "finish"

function M.new_state()
  return { phase = M.IDLE, charge = 0, held_ms = 0, age_ms = 0, restart = 0, restart_age = 0, casts = 0, sound_ms = 0 }
end

function M.active(state) return state.phase ~= M.IDLE end
function M.charging(state) return state.phase == M.CHARGE end
-- The ability is over for good and the script should end it.
function M.wants_end(state) return state.phase == M.DONE end

local function reset(state, rank)
  state.phase, state.rank = M.CHARGE, rank
  state.charge, state.held_ms, state.age_ms = 0, 0, 0
  state.restart, state.restart_age, state.restart_missed = 0, 0, false
  state.cast_done, state.outcome, state.sound_ms = false, nil, 0
end

-- The key was pressed. Returns true for a real start; false when it is the start the restart of the mode time made (the activation
-- goes on in its release).
function M.on_start(state, rank)
  if state.restart == 2 then
    state.restart = 0
    return false
  end
  reset(state, rank)
  return true
end

-- The loader ended the activation (`reason` is its word). Returns how it ended, or nil when the end is the restart's.
function M.on_ability_end(state, reason)
  if state.phase == M.IDLE then return nil end
  if state.restart == 1 then
    state.restart = 2
    return nil
  end
  local outcome = state.outcome
  if not outcome then
    if state.cast_done then outcome = M.ENDED_CAST
    elseif reason == "died" or reason == "gone" then outcome = M.ENDED_DIED
    else outcome = M.ENDED_INTERRUPTED end
  end
  state.phase, state.restart = M.IDLE, 0
  return outcome
end

-- The world was left or the player died: everything stops. Returns the outcome.
function M.finish(state, outcome)
  state.phase, state.restart = M.IDLE, 0
  return outcome
end

-- The script is about to write the mode time 0.
function M.request_restart(state)
  state.restart, state.restart_age = 1, 0
end

-- True once, at the cast (the clip's marker, or the fallback of `step`); false when it is not time or it has happened.
function M.on_cast(state)
  if state.phase ~= M.RELEASE or state.cast_done then return false end
  state.cast_done = true
  state.casts = state.casts + 1
  return true
end

-- One World step of the activation (dt in ms). facts = { alive =, held = (the key), mp = (0 to 1) }. Returns an event or nil.
function M.step(t, state, dt, facts)
  if state.phase == M.IDLE or state.phase == M.DONE then return nil end
  if not facts.alive then
    state.phase, state.outcome = M.DONE, M.ENDED_DIED
    return M.EVENT_FINISH
  end
  if state.phase == M.CHARGE then
    state.held_ms = state.held_ms + dt
    local top = facts.mp
    if top > 1 then top = 1 end
    if top < 0 then top = 0 end
    local charge = state.charge
    if facts.held then charge = charge + t.charge_rate * dt end
    if charge > top then charge = top end
    state.charge = charge
    if facts.held and state.held_ms < t.hold_max_ms then return nil end
    if state.charge < t.min_charge then
      state.phase, state.outcome = M.DONE, M.ENDED_FIZZLED
      return M.EVENT_FIZZLE
    end
    state.phase, state.age_ms = M.RELEASE, 0
    return M.EVENT_RELEASE
  end
  -- release
  state.age_ms = state.age_ms + dt
  if state.restart == 1 then
    state.restart_age = state.restart_age + dt
    if state.restart_age >= t.restart_wait_ms then
      state.restart, state.restart_missed = 0, true
    end
  end
  if not state.cast_done and state.age_ms >= t.cast_fallback_ms then return M.EVENT_CAST end
  if state.age_ms >= t.release_ms then
    state.phase, state.outcome = M.DONE, M.ENDED_CAST
    return M.EVENT_FINISH
  end
  return nil
end

-- The cooldown to leave on the ability when it is over: the whole of it after a cast, none after a cast that did not happen.
function M.cooldown_after(t, outcome, rank)
  if outcome == M.ENDED_CAST then return tuning.cooldown_at(t, rank) end
  return 0
end

-- ---- the charge ------------------------------------------------------------------------------------------------------------

-- The circle's radius in blocks for a charge of 0 to 1: t.radius at none, doubled at a full bar (t.width_gain 1).
function M.radius(t, charge)
  if charge < 0 then charge = 0 end
  if charge > 1 then charge = 1 end
  return t.radius * (1 + t.width_gain * charge)
end

-- The mp left after the charge is spent (never below 0).
function M.mp_after(mp, charge)
  local left = mp - charge
  if left < 0 then return 0 end
  return left
end

-- The slow of the charge: the player walked from `from` ({x, y}, where the last step left them) to x, y (blocks) in one step; they
-- keep only `factor` of that way. Returns the new x, y.
function M.slowed(from, x, y, factor)
  return from.x + (x - from.x) * factor, from.y + (y - from.y) * factor
end

-- True each time `every_ms` has passed (the charge's sound); the first call is due at once.
function M.sound_due(state, dt, every_ms)
  state.sound_ms = state.sound_ms - dt
  if state.sound_ms > 0 then return false end
  state.sound_ms = every_ms
  return true
end

-- ---- the aimed spot --------------------------------------------------------------------------------------------------------

-- Where the circle goes: the aimed point `aim` ({x, y, z} blocks, or nil), pulled back along the line from the player to at most
-- t.range blocks on the ground plan. `from` is the player {x, y, z}, `facing` their unit direction {x, y}: without an aim the spot
-- is t.aim_ahead blocks ahead. Returns { x, y, z, clamped, ahead }.
function M.target(t, from, aim, facing)
  local ax, ay, az
  if aim then
    ax, ay, az = aim.x, aim.y, aim.z
  else
    ax, ay, az = from.x + facing.x * t.aim_ahead, from.y + facing.y * t.aim_ahead, from.z
  end
  local dx, dy = ax - from.x, ay - from.y
  local d = math.sqrt(dx * dx + dy * dy)
  local clamped = false
  if d > t.range then
    local k = t.range / d
    ax, ay, az = from.x + dx * k, from.y + dy * k, from.z + (az - from.z) * k
    clamped = true
  end
  return { x = ax, y = ay, z = az, clamped = clamped, ahead = aim == nil }
end

-- The height of the ground under a spot: `solid(x, y, z)` says whether the block that holds a point is solid (nil when the game
-- cannot be asked, then the spot's own height stands). The search starts t.ground_up over the spot, climbs out of a block it starts
-- in (an aim on a wall or a ceiling), goes down for t.ground_down blocks and returns the top of the first solid block it meets, or
-- the spot's height when there is none.
function M.find_ground(t, solid, spot)
  if not solid then return spot.z end
  local z = math.floor(spot.z + t.ground_up)
  local bottom = z - t.ground_down
  while z > bottom and solid(spot.x, spot.y, z) do z = z - t.ground_probe end
  if solid(spot.x, spot.y, z) then return spot.z end                      -- solid all the way down: no air under it
  while z > bottom and not solid(spot.x, spot.y, z) do z = z - t.ground_probe end
  if solid(spot.x, spot.y, z) then return math.floor(z) + 1 end
  return spot.z
end

-- The server's check of a client's `cast { charge, spot }`. `ev` is the event; `facts` are the server's own:
-- { held_ms (the time its run has lasted), mp (the highest mp its copy of the player had in the run), from = {x, y, z} (that copy's
-- place), aim = {x, y, z} or nil (its aim), facing = {x, y} }. The charge may not pass what the key held for held_ms could charge
-- (plus t.cast_charge_slack), nor the mp; the spot must lie within t.range (plus t.cast_range_slack) of the player and, seen from the
-- player, inside t.cast_cone_deg of the aim (or the facing, with no aim). Returns true, or false and the reason.
function M.check_cast(t, ev, facts)
  local charge, spot = ev.charge, ev.spot
  if type(charge) ~= "number" or charge ~= charge then return false, "no charge" end
  if type(spot) ~= "table" or type(spot.x) ~= "number" or type(spot.y) ~= "number" or type(spot.z) ~= "number" then
    return false, "no spot"
  end
  if spot.x ~= spot.x or spot.y ~= spot.y or spot.z ~= spot.z then return false, "no spot" end
  if charge < t.min_charge then return false, ("charge %.2f under the least %.2f"):format(charge, t.min_charge) end
  local top = facts.mp
  if top > 1 then top = 1 end
  local by_time = t.charge_rate * facts.held_ms
  if by_time < top then top = by_time end
  if charge > top + t.cast_charge_slack then
    return false, ("charge %.2f over the %.2f that %d ms and the mp allow"):format(charge, top, facts.held_ms)
  end
  local from = facts.from
  local dx, dy, dz = spot.x - from.x, spot.y - from.y, spot.z - from.z
  local d = math.sqrt(dx * dx + dy * dy)
  local reach = t.range + t.cast_range_slack
  if d > reach or math.abs(dz) > reach then return false, ("spot %.1f blocks away, over %.1f"):format(d, reach) end
  if d >= t.cast_cone_min then
    local ux, uy
    if facts.aim then ux, uy = facts.aim.x - from.x, facts.aim.y - from.y end
    if not ux or ux * ux + uy * uy < t.cast_cone_min * t.cast_cone_min then ux, uy = facts.facing.x, facts.facing.y end
    local u = math.sqrt(ux * ux + uy * uy)
    if u > 0 then
      local cos = (dx * ux + dy * uy) / (d * u)
      if cos > 1 then cos = 1 elseif cos < -1 then cos = -1 end
      local deg = math.deg(math.acos(cos))
      if deg > t.cast_cone_deg then return false, ("spot %.0f degrees off the aim, over %.0f"):format(deg, t.cast_cone_deg) end
    end
  end
  return true
end

-- ---- the circle and its damage ---------------------------------------------------------------------------------------------

-- The time from the cast to the circle becoming active: the points come down, then the star appears.
function M.activate_ms(t)
  return (t.summon_ticks + t.star_delay_ticks) * units.STEP_MS
end

-- The time from the cast to the circle's last tick of damage.
function M.end_ms(t)
  return M.activate_ms(t) + t.active_ms
end

-- A circle at `spot` ({x, y, z}: z the top of the ground) of `radius` blocks. Its age counts from the cast.
function M.new_circle(t, spot, radius, seed)
  return { x = spot.x, y = spot.y, z = spot.z, radius = radius, seed = seed, age_ms = 0, next_ms = M.activate_ms(t),
    active = false, id = 0, hits = 0 }
end

-- One World step of a circle (dt in ms). Returns how many damage ticks are due, "active" on the step it becomes active (else nil),
-- and true when it is over.
function M.circle_step(t, c, dt)
  c.age_ms = c.age_ms + dt
  local event = nil
  if not c.active and c.age_ms >= M.activate_ms(t) then
    c.active, event = true, "active"
  end
  local due = 0
  if c.active then
    while c.age_ms >= c.next_ms and c.next_ms < M.end_ms(t) do
      due = due + 1
      c.next_ms = c.next_ms + t.tick_ms
    end
  end
  return due, event, c.age_ms >= M.end_ms(t)
end

-- The time from the cast to the points landing (the circle forms from there).
function M.landing_ms(t)
  return t.summon_ticks * units.STEP_MS
end

-- How many fire particles to emit on this step (dt in ms): none before the landing or after the circle is over, else a few every
-- ember_every_ms, more for a wider circle.
function M.embers_due(t, c, dt)
  if c.age_ms < M.landing_ms(t) or c.age_ms >= M.end_ms(t) then return 0 end
  c.ember_ms = (c.ember_ms or 0) + dt
  if c.ember_ms < t.ember_every_ms then return 0 end
  c.ember_ms = c.ember_ms - t.ember_every_ms
  local n = math.ceil(math.pi * c.radius * c.radius * t.ember_density)
  if n > t.ember_max then n = t.ember_max end
  if n < 1 then n = 1 end
  return n
end

-- The light a circle gives the frame (`glow.light_set`): none before its points have landed or once it is over; it swells in over
-- light_in_ms from the landing, flickers a little and dims over the last light_out_ms. Returns nil, or { x, y, z, radius, r, g, b }.
function M.circle_light(t, c)
  local from, to = M.landing_ms(t), M.end_ms(t)
  if c.age_ms < from or c.age_ms >= to then return nil end
  local k = math.min(1, (c.age_ms - from) / t.light_in_ms, (to - c.age_ms) / t.light_out_ms)
  k = k * (1 + t.light_flicker * math.sin(2 * math.pi * t.light_flicker_hz * c.age_ms / units.MS_PER_S))
  local s = t.light_power * k
  local r, g, b = unpack(t.light_color)
  return { x = c.x, y = c.y, z = c.z + t.light_lift, radius = t.light_radius_base + t.light_radius_gain * c.radius,
    r = r * s, g = g * s, b = b * s }
end

-- The light the player gives the frame (`glow.light_set`) at the raised hands' `centre`: full while the glow has all of glow_ms
-- left (the ability is on), dimming with what is left of it after; nil when nothing is left. Returns nil, or
-- { x, y, z, radius, r, g, b }.
function M.player_light(t, centre, left_ms)
  if not left_ms or left_ms <= 0 then return nil end
  local s = t.player_light_power * math.min(1, left_ms / t.glow_ms)
  local r, g, b = unpack(t.light_color)
  return { x = centre.x, y = centre.y, z = centre.z, radius = t.player_light_radius, r = r * s, g = g * s, b = b * s }
end

-- Whether a pulse is due on this step (dt in ms): one at the landing, then each pulse_every_ms until the circle is over.
function M.pulse_due(t, c, dt)
  if c.age_ms < M.landing_ms(t) or c.age_ms >= M.end_ms(t) then return false end
  c.pulse_ms = (c.pulse_ms or t.pulse_every_ms) + dt
  if c.pulse_ms < t.pulse_every_ms then return false end
  c.pulse_ms = c.pulse_ms - t.pulse_every_ms
  return true
end

-- The fields of emtweaks:shockwave for a pulse of `c`: a ring from the middle that reaches the rim and has faded out there.
function M.pulse_def(t, c)
  local run = math.max(1, math.ceil((c.radius - t.pulse_inner - t.pulse_thickness) / t.pulse_expansion))
  local fade_on = math.floor(run * t.pulse_fade_start)
  local alpha = t.pulse_color[#t.pulse_color]
  return {
    pos = { units.to_units(c.x), units.to_units(c.y), units.to_units(c.z + t.pulse_lift) }, facing = { 0, 0, 1 }, inner = t.pulse_inner, thickness = t.pulse_thickness,
    expansion = t.pulse_expansion, life_ticks = run, fade_on_tick = fade_on, fade_speed = alpha / math.max(1, run - fade_on),
    color = t.pulse_color,
  }
end

-- `n` spots of the disc (blocks, even over its area) with a colour each; `rand()` gives 0 up to 1.
function M.ember_spots(t, c, n, rand)
  local out = {}
  for i = 1, n do
    local r = c.radius * math.sqrt(rand())
    local a = 2 * math.pi * rand()
    out[i] = { x = c.x + r * math.cos(a), y = c.y + r * math.sin(a), z = c.z + t.ember_lift,
      color = t.ember_colors[math.floor(rand() * #t.ember_colors) + 1] }
  end
  return out
end

-- Whether a creature ({ x, y, z, feet, half_width }, blocks) stands in the circle: its body reaches into the disc on the ground
-- plan and its feet are within reach of the circle's ground.
function M.in_circle(t, c, creature)
  local dx, dy = creature.x - c.x, creature.y - c.y
  local reach = c.radius + (creature.half_width or 0)
  if dx * dx + dy * dy > reach * reach then return false end
  local rel = (creature.feet or creature.z) - c.z
  return rel >= -t.reach_below and rel <= t.reach_above
end

-- The creatures of the list that stand in the circle, in the order given.
function M.targets(t, c, creatures)
  local out = {}
  for _, creature in ipairs(creatures) do
    if M.in_circle(t, c, creature) then out[#out + 1] = creature end
  end
  return out
end

-- The damage of one tick to one creature, from the player's damage stat.
function M.damage(t, damage_stat)
  return damage_stat * t.damage_mult
end

-- ---- the look --------------------------------------------------------------------------------------------------------------

local function world_pos(x, y, z)
  return { units.to_units(x), units.to_units(y), units.to_units(z) }
end

-- The fields of emtweaks:circle's EmCircleDef (fx.circle) for `c`, summoned from above.
function M.circle_def(t, c)
  local life = t.star_delay_ticks + math.floor(t.active_ms / units.STEP_MS) + t.fade_out_ticks
  return {
    pos = world_pos(c.x, c.y, c.z), radius = c.radius, voxel_size = t.voxel, line_width = t.line_width,
    flame_height = t.flame_height, star_points = t.star_points, star_step = t.star_step, inner_radius = t.inner_radius,
    ring_color = t.ring_color, flame_color = t.flame_color, star_color = t.star_color, seed = c.seed, alpha = t.circle_alpha,
    rise_ticks = t.rise_ticks, star_delay_ticks = t.star_delay_ticks, star_in_ticks = t.star_in_ticks, spin = t.spin,
    pulse = t.pulse, pulse_hz = t.pulse_hz, fade_in_ticks = t.fade_in_ticks, life_ticks = life,
    fade_out_ticks = t.fade_out_ticks, summon_ticks = t.summon_ticks, summon_points = t.summon_points,
    summon_height = c.radius * t.summon_height_ratio, summon_spin = t.summon_spin,
    summon_tilt = t.summon_tilt, summon_voxel = t.summon_voxel, summon_vanish = t.summon_vanish,
  }
end

-- The mark of the target: a ring on the ground at the circle's size from the cast until the points land, then fading.
function M.mark_def(t, c)
  local fade_on = t.summon_ticks - t.mark_fade_ticks
  local alpha = t.mark_color[#t.mark_color]
  return {
    pos = world_pos(c.x, c.y, c.z + t.mark_lift), facing = { 0, 0, 1 }, inner = c.radius - t.mark_thickness,
    thickness = t.mark_thickness, expansion = 0, life_ticks = t.summon_ticks, fade_on_tick = fade_on,
    fade_speed = alpha / t.mark_fade_ticks, color = t.mark_color,
  }
end

-- Where the raised hands are: the centre of the embers, over the player's feet (`feet` in blocks) and ahead of them.
function M.hands_centre(t, player, feet, facing)
  return { x = player.x + facing.x * t.hands_forward, y = player.y + facing.y * t.hands_forward, z = feet + t.hands_up }
end

-- The embers' fields for emtweaks:swirl (fx.swirl), the first ring and the second over it, upside down; `centre` in blocks.
function M.ember_defs(t, centre)
  local life = t.ember_life_ticks
  local first = {
    pos = world_pos(centre.x, centre.y, centre.z), axis = { 0, 0, 1 }, style = 0, radius = t.ember_radius, spin = t.ember_spin,
    grow = 1, fade_in_ticks = t.ember_fade_in_ticks, life_ticks = life,
  }
  local second = {
    pos = world_pos(centre.x, centre.y, centre.z + t.ember2_up), axis = { 0, 0, -1 }, style = 0,
    radius = t.ember_radius * t.ember2_scale, spin = t.ember2_spin, grow = 1, fade_in_ticks = t.ember_fade_in_ticks,
    life_ticks = life,
  }
  return first, second
end

-- Where the second ring sits for a centre in blocks (the first ring's is the centre itself), in world units.
function M.second_pos(t, centre)
  return world_pos(centre.x, centre.y, centre.z + t.ember2_up)
end

function M.first_pos(centre)
  return world_pos(centre.x, centre.y, centre.z)
end

-- The embers' size for a charge of 0 to 1: they swell as the mana builds.
function M.ember_scale(t, charge)
  if charge < 0 then charge = 0 end
  if charge > 1 then charge = 1 end
  return 1 + t.ember_charge_gain * charge
end

-- ---- the skill tooltip -----------------------------------------------------------------------------------------------------

M.TOOLTIP_COOLDOWN, M.TOOLTIP_ACTIVE = "smashcooldown", "retreatdistance"

function M.tooltip_values(t, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(t, rank) / units.MS_PER_S),
    [M.TOOLTIP_ACTIVE] = ("%.0f"):format(t.active_ms / units.MS_PER_S),
  }
end

return M
end

-- @module skills_unleashed.logic.guardian (logic/guardian.lua)
package.preload["skills_unleashed.logic.guardian"] = function(...)
-- skills_unleashed.logic.guardian: the target choice, the taunt's life and the damage cut of the Guardian's Taunt. Pure: no kyubu,
-- no ffi, so a unit test decides it. Every number is a field of the `guardian` block of lib/tuning.lua, passed in as `t`.
--
-- The ability in one line: at the clip's `shout` marker the enemy nearest to the aimed point (within the range of the player) is
-- taunted; for the taunt's time it makes for the Guardian from any distance and hits them softer. The taunt ends early when it is
-- let alone, and the creature cannot be taunted again for a while.
--
-- What a taunt needs from the game, which lib/combat does (the mapping is in mapping/atlas/ai.md, "Target choice"): every World
-- step write the Guardian's id with a large value (`threat_value`) into the taunted creature's threat map; when a taunt ends, write
-- back what the map held before (`prior`) - an entry for the Guardian would keep the creature on them for good.
local volume = require("skills_unleashed.lib.volume")
local units = require("skills_unleashed.lib.units")
local tuning = require("skills_unleashed.lib.tuning")

local M = {}

M.MARKER_SHOUT = "shout"

-- The reasons a taunt ends (the `reason` of an entry `step` returns).
M.ENDED_EXPIRED = "expired"          -- its time ran out
M.ENDED_LET_GO = "let_go"            -- its time ran out after the Guardian had left it alone (it drained faster for a while)
M.ENDED_TARGET_GONE = "target_gone"  -- the taunted creature died or left the World
M.ENDED_TAUNTER_GONE = "taunter_gone"

-- A fresh state: the taunts in force (creature id -> taunt) and the immunities (creature id -> ms left).
function M.new_state()
  return { taunts = {}, immune = {} }
end

-- The taunt's length at `rank` (below 1 reads 1): the base plus a share of the gain that grows with the rank and never ends.
function M.duration_ms(t, rank)
  local steps = rank - 1
  if steps < 0 then steps = 0 end
  return t.taunt_ms + t.taunt_gain_ms * tuning.power(steps, t.rank_scale)
end

-- True when a creature may be taunted now: it is not under a taunt (it cannot change its target, whoever asks) and its immunity,
-- which follows any end of a taunt, is over.
function M.can_taunt(state, id)
  return state.taunts[id] == nil and state.immune[id] == nil
end

-- The creature the shout takes. `player` and `aim` are {x, y, z} in blocks (`aim` may be nil: nothing is aimed at); `enemies`
-- are creature tables (id, x, y, z). The aim is a line from the player to the aimed point, run on past it by `aim_overshoot`; a
-- creature is "at the aim" when it lies inside the cylinder of radius `aim_radius` round that line, so a shot a little beside the
-- enemy still takes it. Of those, the one nearest the line's axis wins (a tie goes to the one nearer the player). Only creatures
-- within `range` of the player count, and one that cannot be taunted is passed over, so the next in line is taken.
-- Returns the creature table, or nil.
function M.pick_target(t, state, player, aim, enemies)
  if aim == nil then return nil end
  local eligible = {}
  for _, c in ipairs(enemies) do
    if M.can_taunt(state, c.id) then eligible[#eligible + 1] = c end
  end
  local near = volume.in_radius(player, eligible, { radius = t.range, reach_z = t.range_reach_z })
  local dx, dy, dz = aim.x - player.x, aim.y - player.y, aim.z - player.z
  local len = math.sqrt(dx * dx + dy * dy + dz * dz)
  local ux, uy, uz = 0, 0, 0
  if len > 0 then ux, uy, uz = dx / len, dy / len, dz / len end
  local best, best_perp, best_along = nil, nil, nil
  for _, e in ipairs(near) do
    local c = e.c
    local vx, vy, vz = c.x - player.x, c.y - player.y, c.z - player.z
    local along = vx * ux + vy * uy + vz * uz
    local px, py, pz = vx - along * ux, vy - along * uy, vz - along * uz
    local perp = math.sqrt(px * px + py * py + pz * pz)
    if along >= 0 and along <= len + t.aim_overshoot and perp <= t.aim_radius then
      if best == nil or perp < best_perp or (perp == best_perp and along < best_along) then
        best, best_perp, best_along = c, perp, along
      end
    end
  end
  return best
end

-- Puts a creature under the taunt of `taunter_id`. `prior` is the threat value the creature's map held for the taunter before (0
-- when it held none): the caller writes it back at the end. Returns the taunt.
function M.start(t, state, rank, target_id, taunter_id, prior)
  local taunt = {
    target = target_id, by = taunter_id, prior = prior or 0,
    left_ms = M.duration_ms(t, rank), idle_ms = 0, fast = false,
  }
  state.taunts[target_id] = taunt
  return taunt
end

-- The threat value to write for the taunter every step.
function M.threat_value(t) return t.threat_value end

-- A hit was seen (attacker and victim ids): a hit between the Guardian and the creature they taunt, either way, is an engagement
-- and the idle time starts again. Returns true when it was one.
function M.on_hit(state, attacker_id, victim_id)
  local taunt = state.taunts[attacker_id]
  if taunt and taunt.by == victim_id then taunt.idle_ms = 0; return true end
  taunt = state.taunts[victim_id]
  if taunt and taunt.by == attacker_id then taunt.idle_ms = 0; return true end
  return false
end

-- The damage a hit does once the taunt's cut is applied: only a taunted creature's hit on its own taunter is cut; every other hit
-- (the same creature's hits on others, anyone else's hits) passes unchanged. Returns the damage and whether it was cut.
function M.scale_damage(t, state, attacker_id, victim_id, damage)
  local taunt = state.taunts[attacker_id]
  if taunt and taunt.by == victim_id then return damage * t.damage_factor, true end
  return damage, false
end

-- The creature id that taunts `id`, or nil.
function M.taunter_of(state, id)
  local taunt = state.taunts[id]
  return taunt and taunt.by or nil
end

-- Moves every taunt and immunity on by `dt_ms`. `alive` is a table id -> true for the creatures that exist and live (the taunted
-- ones and the Guardian). A taunt idle for `letgo_idle_ms` runs out `letgo_rate` times faster until the next engagement. Returns
-- the list of the taunts that ended this step, { target =, by =, prior =, reason = }: the caller restores their threat maps. Each
-- creature that lost a taunt is immune for `immunity_ms`, whatever the reason.
function M.step(t, state, dt_ms, alive)
  for id, left in pairs(state.immune) do
    left = left - dt_ms
    if left <= 0 then state.immune[id] = nil else state.immune[id] = left end
  end
  local ended = {}
  for id, taunt in pairs(state.taunts) do
    local reason = nil
    if not alive[id] then
      reason = M.ENDED_TARGET_GONE
    elseif not alive[taunt.by] then
      reason = M.ENDED_TAUNTER_GONE
    else
      taunt.idle_ms = taunt.idle_ms + dt_ms
      local rate = 1
      if taunt.idle_ms > t.letgo_idle_ms then rate = t.letgo_rate; taunt.fast = true end
      taunt.left_ms = taunt.left_ms - dt_ms * rate
      if taunt.left_ms <= 0 then
        reason = taunt.fast and M.ENDED_LET_GO or M.ENDED_EXPIRED
      end
    end
    if reason then
      ended[#ended + 1] = { target = id, by = taunt.by, prior = taunt.prior, reason = reason }
    end
  end
  table.sort(ended, function(a, b) return a.target < b.target end)
  for _, e in ipairs(ended) do
    state.taunts[e.target] = nil
    state.immune[e.target] = t.immunity_ms
  end
  return ended
end

-- What the caller writes back into the creature's threat map for the taunter when a taunt ends: the value it held before when that
-- was a threat, else a value below zero, which the game's target choice does not take (it looks for a value from zero up), so
-- the creature is free again and the Guardian does not stay its target for good.
function M.restore_value(t, prior)
  if prior > 0 then return prior end
  return t.released_threat
end

-- The colour factors { r, g, b } of a creature that cannot be taunted for now (a copy).
function M.immune_tint(t)
  local out = {}
  for i, v in ipairs(t.immune_tint) do out[i] = v end
  return out
end

-- The colour factors { r, g, b } the taunted creature's draw is multiplied by (a copy: the caller may keep it).
function M.tint(t)
  local out = {}
  for i, v in ipairs(t.tint) do out[i] = v end
  return out
end

-- The rings of the shout for lib/fx, at `pos` (world units): `ring_count` small rings that end at growing radii, so they read as
-- one wave of several. Level on the ground (no facing).
function M.ring_defs(t, pos)
  local defs = {}
  for i = 1, t.ring_count do
    local radius = t.ring_radius * i / t.ring_count
    local grow = radius - t.ring_inner - t.ring_thickness
    if grow < 0 then grow = 0 end
    defs[#defs + 1] = {
      pos = pos,
      inner = t.ring_inner,
      thickness = t.ring_thickness,
      expansion = grow / t.ring_ticks,
      life_ticks = t.ring_ticks,
      fade_on_tick = t.ring_fade_tick,
      fade_speed = t.ring_fade_speed,
      color = t.ring_color,
    }
  end
  return defs
end

-- ---- multiplayer --------------------------------------------------------------------------------------------------------------
-- A joined client sends `taunt { aim, from }` at the shout (the aimed point and where the player stood, blocks); the server picks
-- the target itself from them, owns the taunt (threat writes, the hit cut) and tells every client `taunt_on { target, by, ms }` and
-- `taunt_off { target, by, why }`, from which they draw the tint and the bolts.
M.EVENT_TAUNT = "taunt"
M.EVENT_TAUNT_ON = "taunt_on"
M.EVENT_TAUNT_OFF = "taunt_off"

local function finite(v) return type(v) == "number" and v == v and v ~= math.huge and v ~= -math.huge end
local function point(p) return type(p) == "table" and finite(p.x) and finite(p.y) and finite(p.z) end

-- The server's check of a `taunt` event. `facts`: held_ms (the run's time on the server's clock), from (its copy of the player),
-- aim (its copy's aimed point, or nil) and facing ({ x, y }, the copy's yaw). Returns true, or false and why.
function M.check_taunt(t, ev, facts)
  if not point(ev.aim) or not point(ev.from) then return false, "malformed" end
  if facts.held_ms < t.shout_ms - t.taunt_early_ms then
    return false, ("too early (%d ms into the run)"):format(facts.held_ms)
  end
  local p = facts.from
  local fx, fy, fz = ev.from.x - p.x, ev.from.y - p.y, ev.from.z - p.z
  local fd = math.sqrt(fx * fx + fy * fy)
  if fd > t.taunt_from_slack or math.abs(fz) > t.taunt_from_slack then
    return false, ("from %.1f blocks across and %.1f up of the player"):format(fd, fz)
  end
  local dx, dy = ev.aim.x - p.x, ev.aim.y - p.y
  local d = math.sqrt(dx * dx + dy * dy)
  if d >= t.taunt_cone_min then
    local ux, uy
    if facts.aim then ux, uy = facts.aim.x - p.x, facts.aim.y - p.y end
    if not ux or ux * ux + uy * uy < t.taunt_cone_min * t.taunt_cone_min then ux, uy = facts.facing.x, facts.facing.y end
    local u = math.sqrt(ux * ux + uy * uy)
    if u > 0 then
      local cos = (dx * ux + dy * uy) / (d * u)
      if cos > 1 then cos = 1 elseif cos < -1 then cos = -1 end
      local deg = math.deg(math.acos(cos))
      if deg > t.taunt_cone_deg then
        return false, ("aim %.0f degrees off the player's, over %.0f"):format(deg, t.taunt_cone_deg)
      end
    end
  end
  return true
end

-- A joined client's view of the server's taunts, from its events: a shown taunt is drawn (tint, bolts) and nothing else; its end
-- starts the immunity's blue tint, which runs on the client's clock.
function M.show_on(state, ev)
  if type(ev.target) ~= "number" then return end
  state.taunts[ev.target] = { target = ev.target, by = ev.by, prior = 0, left_ms = ev.ms or 0, idle_ms = 0, fast = false }
  state.immune[ev.target] = nil
end

function M.show_off(t, state, ev)
  if type(ev.target) ~= "number" or not state.taunts[ev.target] then return end
  state.taunts[ev.target] = nil
  state.immune[ev.target] = t.immunity_ms
end

-- Moves a joined client's immunities on by `dt_ms`; a shown taunt whose creature is not in `found` (id -> anything) is dropped.
function M.show_step(state, dt_ms, found)
  for id, left in pairs(state.immune) do
    left = left - dt_ms
    if left <= 0 then state.immune[id] = nil else state.immune[id] = left end
  end
  for id in pairs(state.taunts) do
    if not found[id] then state.taunts[id] = nil end
  end
end

-- The numbers of the skill tooltip at `rank` (0 for an unlearned skill reads rank 1): placeholder name to text, the same source as
-- the ability so the tooltip cannot disagree. As Berserker's, the names are two of the game's own placeholders used as carriers
-- (a name of the mod's own is not resolved: mapping/atlas/ui.md, "Skill tooltip text"): the cooldown and the taunt's length, in
-- seconds. The damage cut is the same at every rank and is written in the dictionary text.
M.TOOLTIP_COOLDOWN, M.TOOLTIP_DURATION = "smashcooldown", "retreatdistance"

function M.tooltip_values(t, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(t, rank) / units.MS_PER_S),
    [M.TOOLTIP_DURATION] = ("%.0f"):format(M.duration_ms(t, rank) / units.MS_PER_S),
  }
end

return M
end

-- @module skills_unleashed.logic.ninja (logic/ninja.lua)
package.preload["skills_unleashed.logic.ninja"] = function(...)
-- skills_unleashed.logic.ninja: the rules of the Ninja's Flash Bomb. Pure: no kyubu, no ffi, so a unit
-- test decides it; the ground is asked through a solid(x, y, z) function the script gives (lib/terrain), as the Scout's trap. Every
-- number is in lib/tuning.lua (`ninja`).
--
-- A cast: the player's clip (on the ground or in the air) launches the player up at `jump`, the bomb leaves the hand at `throw`
-- and flies down until it strikes a creature or the ground (or its time runs out); the blast hurts every enemy within the splash
-- radius, stuns the one struck, kicks the player away from it and starts true stealth; the bounce clip plays.
--
-- A bomb is a table: x, y, z (blocks), vx, vy, vz (blocks a second), t (ms in flight).
-- True stealth is a table in the state: left (ms), until it runs out or the player deals damage. While it lasts the script writes,
-- every World step, the threat `drop_threat` for the player on every enemy, keeps the player out of the AI's first-target scan and
-- holds the game's stealth at `stealth_hold` (probe ninja-scan-skip: one threat write alone does not hold).
local tuning = require("skills_unleashed.lib.tuning")
local units = require("skills_unleashed.lib.units")

local M = {}

M.MARKER_JUMP = "jump"       -- the player's clip: the push up
M.MARKER_THROW = "throw"     -- the player's clip: the bomb leaves the hand

-- How true stealth ended: it ran out (the game's own stealth goes on, draining) or the player dealt damage (no stealth is left).
M.END_EXPIRED = "expired"
M.END_REVEALED = "revealed"

-- The cast's phases (the player's side; the bomb and true stealth go on whatever the ability does):
M.IDLE = "idle"              -- no cast under way
M.THROW = "throw"            -- the clip runs: the jump, then the throw
M.FLIGHT = "flight"          -- the bomb is in the air; the clip holds its last pose
M.BOUNCE = "bounce"          -- the blast's kick: the bounce clip, from its start
M.DONE = "done"              -- over: the script ends the ability

-- What cast_step and on_marker return.
M.EVENT_JUMP, M.EVENT_THROW, M.EVENT_FINISH = "jump", "throw", "finish"

-- The restart (as the Fire Mage's): at the blast the script binds the bounce clip and writes the mode time 0 so that it plays from
-- its start; the loader reads that as a new activation (an `interrupted` end, then a start). request_restart makes on_ability_end
-- and on_start let that pair pass; if it never comes, cast_step gives the wait up after restart_wait_ms.
function M.new_state()
  return { stealth = nil, cast = { phase = M.IDLE, age = 0, air = false, jumped = false, thrown = false, restart = 0, restart_age = 0,
    rank = 1 } }
end

function M.casting(state) return state.cast.phase ~= M.IDLE and state.cast.phase ~= M.DONE end
function M.phase(state) return state.cast.phase end
-- The cast is over for good and the script should end the ability.
function M.wants_end(state) return state.cast.phase == M.DONE end

-- The key was pressed (`on_ground`: where the player was). Returns true for a real start; false for the start the restart made.
function M.on_start(state, rank, on_ground)
  local c = state.cast
  if c.restart == 2 then
    c.restart = 0
    return false
  end
  state.cast = { phase = M.THROW, age = 0, air = not on_ground, jumped = false, thrown = false, restart = 0, restart_age = 0,
    rank = rank }
  return true
end

-- The loader ended the activation. Returns its reason, or nil when the end is the restart's (or no cast was under way).
function M.on_ability_end(state, reason)
  local c = state.cast
  if c.phase == M.IDLE then return nil end
  if c.restart == 1 then
    c.restart = 2
    return nil
  end
  c.phase, c.restart = M.IDLE, 0
  return reason
end

-- The world was left or the player died: the cast stops (the bomb and true stealth are the script's to drop).
function M.forget(state)
  state.cast.phase, state.cast.restart = M.IDLE, 0
  state.stealth = nil
end

local function jump(c)
  if c.phase ~= M.THROW or c.jumped then return nil end
  c.jumped = true
  return M.EVENT_JUMP
end

local function throw(c)
  if c.phase ~= M.THROW or c.thrown then return nil end
  if not c.jumped then return nil end           -- the jump comes first, also when the throw's marker is seen in the same step
  c.thrown = true
  c.phase = M.FLIGHT
  return M.EVENT_THROW
end

-- A marker of the player's clip. Returns the event it makes, or nil.
function M.on_marker(state, name)
  local c = state.cast
  if name == M.MARKER_JUMP then return jump(c) end
  if name == M.MARKER_THROW then return throw(c) end
  return nil
end

-- One World step of the cast (dt in ms). Returns a list of events: a jump or a throw whose marker did not come in time (the clip's
-- own time plus marker_grace_ms: the air clip is bound a step after the start, so its marker at 0 may be missed), and the finish.
function M.cast_step(T, state, dt)
  local c = state.cast
  local out = {}
  if c.phase == M.IDLE or c.phase == M.DONE then return out end
  c.age = c.age + dt
  if c.restart == 1 then
    c.restart_age = c.restart_age + dt
    if c.restart_age >= T.restart_wait_ms then c.restart = 0 end
  end
  if c.phase == M.THROW then
    local jump_at, throw_at = T.jump_ms, T.throw_ms
    if c.air then jump_at, throw_at = 0, T.throw_ms_air end
    if c.age >= jump_at + T.marker_grace_ms then out[#out + 1] = jump(c) end
    if c.age >= throw_at + T.marker_grace_ms then out[#out + 1] = throw(c) end
  elseif c.phase == M.BOUNCE and c.age >= T.bounce_ms then
    c.phase = M.DONE
    out[#out + 1] = M.EVENT_FINISH
  end
  return out
end

-- The bomb burst. Returns true when the cast is still the player's (the bounce clip should start: the script binds it and writes
-- the mode time 0); false when the ability ended before (the blast still kicks the player).
function M.on_impact(state)
  local c = state.cast
  if c.phase ~= M.FLIGHT then return false end
  c.phase, c.age = M.BOUNCE, 0
  c.restart, c.restart_age = 1, 0
  return true
end

-- The player's clip: the air clip when the cast starts off the ground (no crouch; the jump at once).
function M.clip_for(T, on_ground)
  if on_ground then return T.clip end
  return T.clip_air
end

-- How long true stealth lasts at `rank`, ms: the first rank's, and the points lengthen it as the game's own strength saturates.
function M.stealth_ms(T, rank)
  local i = rank
  if i < 1 then i = 1 end
  return T.stealth_ms + T.stealth_gain_ms * tuning.power(i - 1, T.rank_scale)
end

-- The bomb's way, a unit vector, from the camera's view ({x, y, z} of any length, x east, y north, z up). It goes straight down, leaning the
-- same way as the view by `lean_per_degree` of the view's angle away from straight down: a level view leans it a tenth of a right
-- angle. No view, or a view with no horizontal part, gives straight down.
function M.bomb_direction(T, view)
  if not view then return 0, 0, -1 end
  local vx, vy, vz = view.x or 0, view.y or 0, view.z or 0
  local len = math.sqrt(vx * vx + vy * vy + vz * vz)
  local flat = math.sqrt(vx * vx + vy * vy)
  if len <= 0 or flat <= 0 then return 0, 0, -1 end
  local off = math.acos(math.max(-1, math.min(1, -vz / len)))      -- radians away from straight down: 0 to pi
  local lean = off * T.lean_per_degree
  local s = math.sin(lean)
  return vx / flat * s, vy / flat * s, -math.cos(lean)
end

-- A new bomb at the hand of a player whose middle is at `pos` {x, y, z} (blocks), thrown along `view` (see bomb_direction).
function M.throw(T, pos, view)
  local dx, dy, dz = M.bomb_direction(T, view)
  return { x = pos.x, y = pos.y, z = pos.z - T.hand_drop, vx = dx * T.bomb_speed, vy = dy * T.bomb_speed, vz = dz * T.bomb_speed,
    t = 0 }
end

-- Whether a point is inside an enemy's hitbox grown by `pad` (lib/combat.read tables: z the middle, feet the bottom).
local function inside(e, x, y, z, pad)
  local feet = e.feet or e.z
  local top = e.z + (e.z - feet)
  local dx, dy = x - e.x, y - e.y
  local reach = (e.half_width or 0) + pad
  return dx * dx + dy * dy <= reach * reach and z >= feet - pad and z <= top + pad
end

-- One step of the bomb's flight (dt in ms). It is tested every `bomb_step` blocks along its path: the first enemy whose hitbox it
-- enters stops it (the bomb does not pierce), else the ground does. `solid` may be nil (no ground lookup): it then flies until its
-- time runs out. Returns nil while it flies, or the impact { x, y, z, struck = the enemy or nil, why = "creature", "ground" or
-- "time" }. A ground impact is the last point outside the ground.
function M.fly(T, bomb, dt_ms, enemies, solid)
  local dt = dt_ms / units.MS_PER_S
  local sx, sy, sz = bomb.vx * dt, bomb.vy * dt, bomb.vz * dt
  local dist = math.sqrt(sx * sx + sy * sy + sz * sz)
  local n = math.max(1, math.ceil(dist / T.bomb_step))
  for i = 1, n do
    local x, y, z = bomb.x + sx * i / n, bomb.y + sy * i / n, bomb.z + sz * i / n
    local best, best_d = nil, nil
    for _, e in ipairs(enemies) do
      if inside(e, x, y, z, T.bomb_radius) then
        local dx, dy, dz = e.x - bomb.x, e.y - bomb.y, e.z - bomb.z
        local d = dx * dx + dy * dy + dz * dz
        if not best or d < best_d or (d == best_d and (e.id or 0) < (best.id or 0)) then best, best_d = e, d end
      end
    end
    if best then
      bomb.x, bomb.y, bomb.z = x, y, z
      return { x = x, y = y, z = z, struck = best, why = "creature" }
    end
    if solid and solid(x, y, z) then
      local px, py, pz = bomb.x + sx * (i - 1) / n, bomb.y + sy * (i - 1) / n, bomb.z + sz * (i - 1) / n
      bomb.x, bomb.y, bomb.z = px, py, pz
      return { x = px, y = py, z = pz, why = "ground" }
    end
  end
  bomb.x, bomb.y, bomb.z = bomb.x + sx, bomb.y + sy, bomb.z + sz
  bomb.t = bomb.t + dt_ms
  if bomb.t >= T.bomb_max_ms then return { x = bomb.x, y = bomb.y, z = bomb.z, why = "time" } end
  return nil
end

-- The distance from a point to an enemy's hitbox (0 inside it), blocks.
local function to_body(e, x, y, z)
  local feet = e.feet or e.z
  local top = e.z + (e.z - feet)
  local dx, dy = x - e.x, y - e.y
  local flat = math.max(0, math.sqrt(dx * dx + dy * dy) - (e.half_width or 0))
  local up = 0
  if z < feet then up = feet - z elseif z > top then up = z - top end
  return math.sqrt(flat * flat + up * up)
end

-- Who the blast hurts: every enemy whose hitbox is within `splash_radius` of the impact, nearest first, each { c, d, stun_ms }. The
-- enemy the bomb struck is always in it, and is the only one stunned.
function M.victims(T, impact, enemies)
  local out = {}
  local struck = impact.struck
  for _, e in ipairs(enemies) do
    local is_struck = struck ~= nil and e.id == struck.id
    local d = to_body(e, impact.x, impact.y, impact.z)
    if is_struck or d <= T.splash_radius then
      local stun = 0
      if is_struck then stun = T.stun_ms end
      out[#out + 1] = { c = e, d = d, stun_ms = stun }
    end
  end
  table.sort(out, function(p, q)
    if p.d ~= q.d then return p.d < q.d end
    return (p.c.id or 0) < (q.c.id or 0)
  end)
  return out
end

-- The damage of the blast to each victim, from the player's damage stat.
function M.damage(T, stat) return stat * T.damage_mult end

-- The player's velocity at the blast (blocks a second): away from the impact, from the impact to the player's middle; a player
-- right on the impact goes straight up.
function M.blast_push(T, player, impact)
  local dx, dy, dz = player.x - impact.x, player.y - impact.y, player.z - impact.z
  local len = math.sqrt(dx * dx + dy * dy + dz * dz)
  if len <= 0 then return 0, 0, T.blast_speed end
  return dx / len * T.blast_speed, dy / len * T.blast_speed, dz / len * T.blast_speed
end

-- Starts true stealth at `rank` (a new one replaces one that is on).
function M.stealth_start(T, state, rank)
  state.stealth = { left = M.stealth_ms(T, rank) }
  return state.stealth
end

function M.stealthed(state) return state.stealth ~= nil end

-- One step of true stealth (dt in ms). Returns M.END_EXPIRED on the step it runs out, else nil.
function M.stealth_step(state, dt_ms)
  local s = state.stealth
  if not s then return nil end
  s.left = s.left - dt_ms
  if s.left <= 0 then
    state.stealth = nil
    return M.END_EXPIRED
  end
  return nil
end

-- A hit seen at the game's hit sites while true stealth is on: one the player deals ends it (M.END_REVEALED); one the player takes,
-- or one between others, does not. A hit with no damage (a miss) does not count. Returns the end, or nil.
function M.stealth_on_hit(state, player_id, attacker_id, victim_id, damage)
  if not state.stealth then return nil end
  if attacker_id ~= player_id or victim_id == player_id then return nil end
  if not damage or damage <= 0 then return nil end
  state.stealth = nil
  return M.END_REVEALED
end

-- ---- a joined game ------------------------------------------------------------------------------------------------------------

-- The event a joined client sends at the throw: `bomb { from, view }` on skills_unleashed:ability, `from` the player's middle and
-- `view` the camera's view (or none: straight down). The server's events on skills_unleashed:world: `stealth_on { owner, ms }` when
-- true stealth starts and `stealth_off { owner, why }` (END_EXPIRED, END_REVEALED or "gone") when it ends; for bystanders also
-- `bomb { owner, from, view }` when it takes a bomb (same kind as the client's, another channel) and `burst { owner, x, y, z }` where
-- its bomb burst.
M.EVENT_BOMB = "bomb"
M.EVENT_BURST = "burst"
M.EVENT_STEALTH_ON = "stealth_on"
M.EVENT_STEALTH_OFF = "stealth_off"

local function finite(v) return type(v) == "number" and v == v and v ~= math.huge and v ~= -math.huge end

-- The server's check of a `bomb` event against its own copy of the run and the player. `facts`: held_ms (the run's own clock),
-- from {x, y, z} (the server's copy of the player). Returns true, or false and why. The view needs no cone: whatever it is, the bomb
-- leans at most lean_per_degree of a half turn away from straight down (bomb_direction).
function M.check_bomb(T, ev, facts)
  local f = ev.from
  if type(f) ~= "table" or not finite(f.x) or not finite(f.y) or not finite(f.z) then return false, "malformed" end
  local v = ev.view
  if v ~= nil and (type(v) ~= "table" or not finite(v.x) or not finite(v.y) or not finite(v.z)) then return false, "malformed" end
  local first = math.min(T.throw_ms, T.throw_ms_air)
  if facts.held_ms < first - T.bomb_early_ms then return false, ("too early (%d ms into the run)"):format(facts.held_ms) end
  local dx, dy, dz = f.x - facts.from.x, f.y - facts.from.y, f.z - facts.from.z
  local d = math.sqrt(dx * dx + dy * dy)
  if d > T.bomb_from_slack or math.abs(dz) > T.bomb_from_slack then
    return false, ("from %.1f blocks across and %.1f up of the player"):format(d, dz)
  end
  return true
end

-- The skill tooltip's placeholders at `rank`: the cooldown and true stealth in seconds.
M.TOOLTIP_COOLDOWN = "smashcooldown"
M.TOOLTIP_STEALTH = "retreatdistance"
function M.tooltip_values(T, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(T, rank) / units.MS_PER_S),
    [M.TOOLTIP_STEALTH] = ("%.1f"):format(M.stealth_ms(T, rank) / units.MS_PER_S),
  }
end

return M
end

-- @module skills_unleashed.logic.roster (logic/roster.lua)
package.preload["skills_unleashed.logic.roster"] = function(...)
-- skills_unleashed.logic.roster: which abilities the mod defines, in which order, and the class of each. Pure. The client and the
-- server both read it: the loader numbers an ability by its place in the registry, and Server.exe looks a player's mode number up in
-- its own registry, so the server must define the same ids in the same order as the client (replay server-berserker-0720: with one
-- ability on the server the client's number found nothing there). Also the client's main.lua and the server's server/main.lua.
local M = {}

-- The specializations that have an ability, in the order they were delivered. The names are the game's, lower-cased.
M.ENABLED = { "berserker", "guardian", "sniper", "scout", "fire_mage", "water_mage", "ninja", "assassin" }

M.CLASS = {
  berserker = "warrior", guardian = "warrior",
  sniper = "ranger", scout = "ranger",
  fire_mage = "mage", water_mage = "mage",
  ninja = "rogue", assassin = "rogue",
}

-- The ids of the abilities a specialization defines besides its own, in the order it defines them (the Assassin's clone clips:
-- abilities on no bar). `t` is the specialization's tuning block.
function M.extra_ids(spec, t)
  local ids = {}
  if spec == "assassin" and t.clone_clips then
    local keys = {}                                  -- the client sorts the keys of t.clone_clips; the same order here
    for key in pairs(t.clone_clips) do keys[#keys + 1] = key end
    table.sort(keys)
    for _, key in ipairs(keys) do ids[#ids + 1] = t.clone_clips[key] end
  end
  return ids
end

return M
end

-- @module skills_unleashed.logic.scout (logic/scout.lua)
package.preload["skills_unleashed.logic.scout"] = function(...)
-- skills_unleashed.logic.scout: the rules of the Scout's Trap Deployment. Pure: no kyubu, no ffi; the
-- ground is asked through a solid(x, y, z) function the script gives (lib/terrain over kyubu.game.world_block), so a unit test
-- builds its own ground. Every number is in lib/tuning.lua (`scout`).
--
-- A trap is a table: id, phase, t (ms in the phase), x, y, z (blocks: the middle of its bottom), vx, vy, vz, yaw (degrees, the ghost's),
-- fx, fy (the throw's direction on the ground), born (its order), start_z. Its phases:
--   flight    thrown from the hand, falls under gravity, bounces, slides to rest (fly)
--   opening   the clip scout_trap_open plays; `open` is the jaws flat (a sound), the end of the clip arms it
--   armed     lies open until an enemy that is neither stunned nor snared is on it (should_trigger), or its life ends
--   sprung    the clip scout_trap_snap plays; `hit` is the damage, the snare and the click; it lasts the snare
--   fading    fades out, then it is gone
local tuning = require("skills_unleashed.lib.tuning")
local units = require("skills_unleashed.lib.units")
local volume = require("skills_unleashed.lib.volume")

local M = {}

M.MARKER_SPAWN = "spawn"     -- the player's clip: the hand is in front, the trap leaves it
M.MARKER_OPEN = "open"       -- the opening clip: the jaws hit the ground
M.MARKER_HIT = "hit"         -- the snap clip: the jaws meet

function M.new_state() return { traps = {}, next_id = 1 } end

-- A new trap thrown by a player at `pos` {x, y, z} (blocks) facing `yaw_deg`. Not yet in the state (add does that).
function M.throw(T, state, pos, yaw_deg)
  local fx, fy = units.facing(yaw_deg)
  local id = state.next_id
  state.next_id = id + 1
  return {
    id = id, phase = "flight", t = 0, born = id,
    x = pos.x + fx * T.throw_ahead, y = pos.y + fy * T.throw_ahead, z = pos.z + T.throw_up,
    vx = fx * T.throw_speed, vy = fy * T.throw_speed, vz = T.throw_lift,
    yaw = yaw_deg, fx = fx, fy = fy, start_z = pos.z + T.throw_up, ground = pos.z, grounded = false,
  }
end

-- Puts `trap` in the state; the oldest of the same owner (trap.owner: the server's traps of several players share one state; nil on a
-- single-player client) beyond max_traps are taken out. Returns the list of traps taken out.
function M.add(T, state, trap)
  local list = state.traps
  list[#list + 1] = trap
  local removed = {}
  while true do
    local oldest, count = nil, 0
    for i, tr in ipairs(list) do
      if tr.owner == trap.owner then
        count = count + 1
        if not oldest or tr.born < list[oldest].born then oldest = i end
      end
    end
    if count <= T.max_traps then break end
    removed[#removed + 1] = table.remove(list, oldest)
  end
  return removed
end

function M.remove(state, trap)
  for i, tr in ipairs(state.traps) do
    if tr == trap then table.remove(state.traps, i); return true end
  end
  return false
end

local function speed(trap) return math.sqrt(trap.vx * trap.vx + trap.vy * trap.vy) end

local function come_to_rest(trap)
  trap.vx, trap.vy, trap.vz = 0, 0, 0
  trap.phase, trap.t = "opening", 0
  return true
end

-- One step of the flight (dt in ms). `solid(x, y, z)` says whether the block at a point is solid; nil when the ground cannot be
-- asked: the trap then lands at the height of the player's position when it was thrown. Returns true when it came to rest (it
-- is then in phase "opening"). A landing in this step leaves its fall speed (blocks a second) in trap.impact, for the bounce's
-- sound: the caller clears it.
function M.fly(T, trap, dt_ms, solid)
  local dt = dt_ms / units.MS_PER_S
  trap.t = trap.t + dt_ms
  if trap.t >= T.flight_max_ms or trap.z < trap.start_z - T.fall_max then return come_to_rest(trap) end
  local function hits(x, y, z)
    if solid then return solid(x, y, z) end
    return z <= trap.ground
  end
  local function floor_at(z)
    if solid then return math.floor(z) + 1 end
    return trap.ground
  end
  -- forward: a wall a little above the bottom stops it
  local nx, ny = trap.x + trap.vx * dt, trap.y + trap.vy * dt
  if (trap.vx ~= 0 or trap.vy ~= 0) and solid and solid(nx, ny, trap.z + T.step_up) then
    trap.vx, trap.vy = 0, 0
    nx, ny = trap.x, trap.y
  end
  trap.x, trap.y = nx, ny
  if trap.grounded then
    -- sliding: friction, and a fall when the ground is gone
    local sp = speed(trap)
    local left = sp - T.friction * dt
    if left <= 0 then trap.vx, trap.vy = 0, 0
    else trap.vx, trap.vy = trap.vx * left / sp, trap.vy * left / sp end
    if not hits(trap.x, trap.y, trap.z - T.ground_probe) then
      trap.grounded = false
    elseif speed(trap) < T.rest_speed then
      return come_to_rest(trap)
    end
    if trap.grounded then return false end
  end
  trap.vz = trap.vz - T.gravity * dt
  local nz = trap.z + trap.vz * dt
  if trap.vz <= 0 and hits(trap.x, trap.y, nz) then
    nz = floor_at(nz)
    local fall = -trap.vz
    trap.impact = fall
    if fall > T.bounce_min then
      trap.vz = fall * T.bounce
      trap.vx, trap.vy = trap.vx * T.bounce_keep, trap.vy * T.bounce_keep
    else
      trap.vz = 0
      trap.grounded = true
    end
  end
  trap.z = nz
  if trap.grounded and speed(trap) < T.rest_speed then return come_to_rest(trap) end
  return false
end

-- One step of a trap that is not flying (dt in ms; open_ms and snap_ms the lengths of the two clips). Returns the phase it entered,
-- or nil: "armed" (the opening is over), "fading" (its life or its snare is over: the snare ends here), "gone". A trap that follows
-- the server (trap.follow: a joined client's) only counts its time: its phases come from the server's events (M.on_event).
function M.advance(T, trap, dt_ms, open_ms)
  trap.t = trap.t + dt_ms
  if trap.follow then return nil end
  local p = trap.phase
  if p == "opening" and trap.t >= open_ms then
    trap.phase, trap.t = "armed", 0
    return "armed"
  elseif (p == "armed" and trap.t >= T.armed_ms) or (p == "sprung" and trap.t >= T.snare_ms) then
    trap.phase, trap.t = "fading", 0
    return "fading"
  elseif p == "fading" and trap.t >= T.fade_ms then
    trap.phase = "gone"
    return "gone"
  end
  return nil
end

-- ---- the server's word --------------------------------------------------------------------------------------------------------

-- Whether the server takes a joined client's `throw { from = {x, y, z}, yaw }` event. `facts`: held_ms (the server's own clock of the
-- run), after_ms (ms since the run ended; nil while it goes on), from {x, y, z} (the server's copy of the player) and yaw (its facing,
-- degrees). True, or false and why. The window: from spawn_ms less throw_early_ms into the run to throw_late_ms after its end; the
-- place: within throw_range_slack blocks on the plan and in z; the facing: within throw_cone_deg.
function M.check_throw(T, ev, facts)
  local f = ev.from
  if type(f) ~= "table" or type(f.x) ~= "number" or type(f.y) ~= "number" or type(f.z) ~= "number" or type(ev.yaw) ~= "number" then
    return false, "malformed"
  end
  for _, v in ipairs({ f.x, f.y, f.z, ev.yaw }) do
    if v ~= v or v == math.huge or v == -math.huge then return false, "malformed" end
  end
  if facts.held_ms < T.spawn_ms - T.throw_early_ms then
    return false, ("too early (%d ms into the run)"):format(facts.held_ms)
  end
  if facts.after_ms and facts.after_ms > T.throw_late_ms then
    return false, ("too late (%d ms after the run)"):format(facts.after_ms)
  end
  local dx, dy, dz = f.x - facts.from.x, f.y - facts.from.y, f.z - facts.from.z
  local d = math.sqrt(dx * dx + dy * dy)
  if d > T.throw_range_slack or math.abs(dz) > T.throw_range_slack then
    return false, ("from %.1f blocks across and %.1f up of the player"):format(d, dz)
  end
  local half = units.FULL_TURN_DEG / 2
  local off = math.abs((ev.yaw - facts.yaw + half) % units.FULL_TURN_DEG - half)
  if off > T.throw_cone_deg then return false, ("yaw %.0f degrees off the player's"):format(off) end
  return true
end

-- The trap of the server's `trap_thrown` event, as a joined client keeps it: it follows the server (advance changes no phase).
function M.from_event(T, ev)
  local fx, fy = units.facing(ev.yaw)
  return {
    id = ev.id, sid = ev.id, owner = ev.owner, run = ev.run, phase = "flight", t = 0, born = ev.id, follow = true,
    x = ev.x, y = ev.y, z = ev.z, vx = ev.vx, vy = ev.vy, vz = ev.vz,
    yaw = ev.yaw, fx = fx, fy = fy, start_z = ev.z, ground = ev.ground or ev.z, grounded = false,
  }
end

-- A server event on a trap that follows it (trap_landed, trap_armed, trap_sprung, trap_fading): the phase the server says, and the
-- place it landed at. Returns the phase entered, or nil (an event of a phase it is past, or of another kind).
local ORDER = {}
for i, phase in ipairs({ "flight", "opening", "armed", "sprung", "fading", "gone" }) do ORDER[phase] = i end
local EVENT_PHASE = { trap_landed = "opening", trap_armed = "armed", trap_sprung = "sprung", trap_fading = "fading" }
function M.on_event(trap, ev)
  local phase = EVENT_PHASE[ev.kind]
  if not phase then return nil end
  if ev.kind == "trap_landed" and type(ev.x) == "number" then
    trap.x, trap.y, trap.z = ev.x, ev.y, ev.z
    trap.vx, trap.vy, trap.vz, trap.grounded = 0, 0, 0, true
  end
  if ORDER[trap.phase] >= ORDER[phase] then return nil end
  trap.phase, trap.t = phase, 0
  return phase
end

-- The trap's opacity now (it fades in its last phase).
function M.alpha(T, trap)
  if trap.phase ~= "fading" then return 1 end
  local a = 1 - trap.t / T.fade_ms
  if a < 0 then return 0 end
  return a
end

-- The enemies over a trap, nearest first, as lib/volume entries (c = a copy of the enemy with `middle` its position's z and z its
-- feet, d, dx, dy). An enemy counts when its feet are from `below` under to `above` over the trap (a creature's position is the
-- middle of its hitbox, so a tall one's is far above a trap it stands on), and on the ground plan its
-- middle is within `radius` of the trap's, or its body overlaps the trap (half its width plus the trap's own radius): a big monster
-- whose body covers the trap counts though its middle is farther (`half_width` missing reads 0, `feet` missing reads z).
local function over(T, trap, enemies, radius, below, above)
  local out = {}
  for _, e in ipairs(enemies) do
    local c = {}
    for k, v in pairs(e) do c[k] = v end
    c.middle, c.z = e.z, e.feet or e.z
    local up = c.z - trap.z
    local dx, dy = c.x - trap.x, c.y - trap.y
    local d = math.sqrt(dx * dx + dy * dy)
    if up >= -below and up <= above and d <= math.max(radius, (e.half_width or 0) + T.trap_radius) then
      out[#out + 1] = { c = c, d = d, dx = dx, dy = dy }
    end
  end
  table.sort(out, function(p, q)
    if p.d ~= q.d then return p.d < q.d end
    return (p.c.id or 0) < (q.c.id or 0)
  end)
  return out
end
M.over = over

-- Whether an armed trap goes off: an enemy (lib/combat.read tables) is over it that is neither stunned nor snared (`is_snared(id)`).
function M.should_trigger(T, trap, enemies, is_snared)
  if trap.phase ~= "armed" then return false end
  for _, e in ipairs(over(T, trap, enemies, T.trigger_radius, T.trigger_below, T.trigger_above)) do
    if not e.c.stunned and not is_snared(e.c.id) then return true end
  end
  return false
end

-- The enemy nearest the trap on the ground plan, for the log: the entry and its feet's height above the trap, or nil.
function M.nearest(T, trap, enemies)
  local list = over(T, trap, enemies, T.debug_radius, T.debug_radius, T.debug_radius)
  if not list[1] then return nil end
  return list[1], list[1].c.z - trap.z
end

-- Sets the trap off: the snap clip starts.
function M.spring(trap)
  trap.phase, trap.t = "sprung", 0
end

-- Who the jaws hurt, at the `hit` marker: the closest enemy in reach that is not snared already is the target (the closest of all
-- when every one is), snared when `can_snare(id)`; every other enemy in reach is secondary. Returns { target = entry or nil,
-- snare = bool, others = { entries } } (lib/volume entries: c, d, dx, dy).
function M.victims(T, trap, enemies, is_snared, can_snare)
  local inside = over(T, trap, enemies, T.reach, T.reach_z, T.reach_z)
  local pick = nil
  for i, e in ipairs(inside) do
    if not is_snared(e.c.id) then pick = i; break end
  end
  pick = pick or (inside[1] and 1)
  local out = { target = nil, snare = false, others = {} }
  for i, e in ipairs(inside) do
    if i == pick then out.target = e else out.others[#out.others + 1] = e end
  end
  if out.target then out.snare = can_snare(out.target.c.id) and true or false end
  return out
end

-- The damage to the target and to the others, from the player's damage stat.
function M.damage(T, stat)
  local d = stat * T.damage_factor
  return d, d * T.secondary_factor
end

-- The knock of a secondary enemy: the push on the ground (blocks a second, away from the trap) and the lift.
function M.knock(T, trap, entry)
  local ax, ay = volume.away(entry, { x = trap.fx, y = trap.fy }, T.away_min)
  return ax * T.knock_push, ay * T.knock_push, T.knock_lift
end

-- The volume of a sound at a trap `d` blocks from the player: full at the player, nothing from sound_range on.
function M.sound_volume(T, d)
  local f = 1 - d / T.sound_range
  if f < 0 then f = 0 end
  return T.sound_volume * f
end

-- The volume of a landing's sound (the game's sound fades with the distance itself): 0 under bounce_sound_min, full from
-- bounce_loud_speed.
function M.bounce_volume(T, impact)
  if not impact or impact < T.bounce_sound_min then return 0 end
  return math.min(1, impact / T.bounce_loud_speed)
end

-- Whether a trap shows its V and its ring: from the landing until it goes off.
function M.marked(trap) return trap.phase == "opening" or trap.phase == "armed" end

-- The V over a trap at `clock_ms` (any running clock): its middle {x, y, z} in blocks and its yaw in degrees (it bobs and turns).
function M.marker_place(T, trap, clock_ms)
  local bob = T.marker_bob * math.sin(2 * math.pi * clock_ms / T.marker_bob_ms)
  return { x = trap.x, y = trap.y, z = trap.z + T.marker_height + bob }, (T.marker_spin * clock_ms / units.MS_PER_S) % units.FULL_TURN_DEG
end

-- The still ring round a waiting trap (an fx.shockwave def, pos in blocks): its outer edge at the trigger radius, no growth, no fade.
function M.ring_def(T, trap)
  return {
    pos = { trap.x, trap.y, trap.z + T.ring_lift },
    inner = T.trigger_radius - T.ring_thickness, thickness = T.ring_thickness, expansion = 0,
    life_ticks = T.ring_life_ticks, fade_on_tick = 0, fade_speed = 0, color = T.ring_color,
  }
end

-- The ring as the trap goes off: from the same place, growing and fading out.
function M.pulse_def(T, trap)
  local d = M.ring_def(T, trap)
  d.expansion, d.life_ticks, d.fade_speed = T.pulse_expansion, T.pulse_life_ticks, T.pulse_fade_speed
  return d
end

-- The skill tooltip's placeholders at `rank` (assets/text/dict_en.xml, AbilityTrap): the cooldown and the snare in seconds.
M.TOOLTIP_COOLDOWN = "smashcooldown"
M.TOOLTIP_SNARE = "retreatdistance"
function M.tooltip_values(T, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(T, rank) / units.MS_PER_S),
    [M.TOOLTIP_SNARE] = ("%.0f"):format(T.snare_ms / units.MS_PER_S),
  }
end

return M
end

-- @module skills_unleashed.logic.sniper (logic/sniper.lua)
package.preload["skills_unleashed.logic.sniper"] = function(...)
-- skills_unleashed.logic.sniper: the life of the Sniper's Bow of Light, the summoning's materializing bow and falling motes, the
-- mp guard, the charge's sound and the arrow's damage. Pure: no kyubu, no ffi, so a unit test decides it. Every number is a field of the `sniper` block of lib/tuning.lua,
-- passed in as `t`.
--
-- The ability in one line: the summoning (the ability's own mode) puts a bow of light in the player's hands, who then holds it for
-- a time and has one shot: an arrow that flies straight through every enemy. The bow goes after the shot or when the time is up, and
-- only then the cooldown runs.
--
-- The phases of one activation:
--   idle     nothing is going on
--   summon   the ability's mode: at `spawn` the hands reach the clasp (the spawn sound), `catch` puts the bow in the hand
--   held     the ability is over and the player has the bow: they may charge and shoot once
--   shot     the arrow is away; the bow stays for the rest of the shot's own mode
local tuning = require("skills_unleashed.lib.tuning")
local units = require("skills_unleashed.lib.units")

local M = {}

M.MARKER_SPAWN, M.MARKER_CATCH = "spawn", "catch"
M.IDLE, M.SUMMON, M.HELD, M.SHOT = "idle", "summon", "held", "shot"

-- Why the bow went (what `step` and `on_ability_end` return).
M.ENDED_SHOT = "shot"                -- the one arrow was shot
M.ENDED_EXPIRED = "expired"          -- the time with the bow ran out
M.ENDED_DIED = "died"                -- the player died or left
M.ENDED_ABORTED = "aborted"          -- the summoning was broken off before the take

function M.new_state()
  return { phase = M.IDLE, has_bow = false }
end

-- True from the press until the bow is gone: the cooldown is held at its full length meanwhile.
function M.active(state) return state.phase ~= M.IDLE end

-- The ability started: `mp` is what the player has now, which the guard keeps.
function M.begin(state, rank, mp)
  state.phase = M.SUMMON
  state.rank = rank
  state.has_bow = false
  state.spawned = false
  state.held_ms = 0
  state.charging = false
  state.ring_ms, state.sound_ms = 0, 0
  state.summon_ms, state.motes_ms = 0, 0
  state.charge = 0
  state.linger_ms = 0
  state.guard_floor = mp
  state.guard_left = nil             -- nil: the guard has no end yet (it gets one at the take)
end

-- The `spawn` marker: the hands have reached the clasp, where the bow is called. Returns true the first time.
function M.on_spawn(state)
  if state.phase ~= M.SUMMON or state.spawned then return false end
  state.spawned = true
  state.spawned_ms = state.summon_ms
  return true
end

-- True once the materializing bow is due (ghost_from_ms of the summoning).
function M.ghost_due(t, state) return state.phase == M.SUMMON and state.summon_ms >= t.ghost_from_ms end

-- The materializing bow's opacity: 0 until ghost_from_ms, then a straight line to 1 in ghost_fade_ms.
function M.ghost_alpha(t, state)
  local a = (state.summon_ms - t.ghost_from_ms) / t.ghost_fade_ms
  if a < 0 then return 0 end
  if a > 1 then return 1 end
  return a
end

-- The `catch` marker: the player has the bow. Returns true the first time.
function M.on_catch(t, state)
  if state.phase ~= M.SUMMON or state.has_bow then return false end
  state.has_bow = true
  state.guard_left = t.mp_guard_after_ms
  return true
end

-- The ability's mode ended with `reason` (the loader's: done, cancelled, stunned, died, interrupted, gone). With the bow in the
-- hand the held time starts, whatever broke the mode off; without it the summoning failed. Returns nil while the bow lives on, or
-- the reason it is over (ENDED_*).
function M.on_ability_end(state, reason)
  if state.phase ~= M.SUMMON then return nil end
  if reason == "died" or reason == "gone" then return M.finish(state, M.ENDED_DIED) end
  if not state.has_bow then return M.finish(state, M.ENDED_ABORTED) end
  state.phase = M.HELD
  state.held_ms = 0
  return nil
end

-- Everything is over: back to idle. Returns `why`.
function M.finish(state, why)
  state.phase = M.IDLE
  state.has_bow = false
  state.charging = false
  state.guard_floor, state.guard_left = nil, nil
  return why
end

-- The mp guard: the mp may not fall while it is up (the summoning and a time after the take), so the mp that runs down by
-- itself is put back; mp that grew is kept. Returns the mp to write, or nil when nothing is to be written.
function M.guard_mp(state, mp)
  local floor = state.guard_floor
  if floor == nil then return nil end
  if mp < floor then return floor end
  state.guard_floor = mp
  return nil
end

-- True while the mp guard is up.
function M.guarding(state) return state.guard_floor ~= nil end

-- One World step of `dt_ms`. `seen` is what the game shows: alive (the player lives), charging (the bow's charge mode),
-- shooting (the bow's shot mode). Returns nil, or the reason the bow is over (the state is idle then).
function M.step(t, state, dt_ms, seen)
  if state.phase == M.IDLE then return nil end
  if not seen.alive then return M.finish(state, M.ENDED_DIED) end
  if state.phase == M.SUMMON then state.summon_ms = state.summon_ms + dt_ms end
  if state.guard_left ~= nil then
    state.guard_left = state.guard_left - dt_ms
    if state.guard_left <= 0 then state.guard_floor, state.guard_left = nil, nil end
  end
  if state.phase == M.HELD then
    if seen.charging then
      if not state.charging then state.ring_ms, state.sound_ms = 0, 0 end
      state.charging = true
    else
      state.charging = false
    end
    state.held_ms = state.held_ms + dt_ms
    -- a charge or a shot that is under way when the time is up is let finish: the bow is not taken out of a drawn hand
    if state.held_ms >= t.hold_ms and not seen.charging and not seen.shooting then
      return M.finish(state, M.ENDED_EXPIRED)
    end
  elseif state.phase == M.SHOT then
    state.linger_ms = state.linger_ms + dt_ms
    if not seen.shooting or state.linger_ms >= t.shot_linger_ms then
      return M.finish(state, M.ENDED_SHOT)
    end
  end
  return nil
end

-- True when the player may charge and shoot the bow of light: both mouse buttons charge, and the release is one arrow.
function M.armed(state) return state.phase == M.HELD end

-- The charge as a fraction: the charged mp, 0 to 1.
function M.charge_fraction(charged_mp)
  if charged_mp ~= charged_mp or charged_mp < 0 then return 0 end
  if charged_mp > 1 then return 1 end
  return charged_mp
end

-- The multiple of the damage stat at a charge (0 to 1): a straight line from damage_mult to damage_mult_full.
function M.damage_mult(t, charge)
  local c = M.charge_fraction(charge)
  return t.damage_mult + (t.damage_mult_full - t.damage_mult) * c
end

-- The arrow's damage for a damage stat and a charge.
function M.arrow_damage(t, damage_stat, charge)
  return damage_stat * M.damage_mult(t, charge)
end

-- The arrow was made with `charge`: the bow has had its shot. Returns false when no shot was due (not held).
function M.on_arrow(state, charge)
  if state.phase ~= M.HELD then return false end
  state.phase = M.SHOT
  state.charge = M.charge_fraction(charge)
  state.charging = false
  state.linger_ms = 0
  state.guard_floor, state.guard_left = nil, nil      -- the shot spends its mp as usual
  return true
end

-- The arrow's direction, a unit vector (dx, dy, dz), or nil for the game's own aim. `aim` is the point the crosshair is on and
-- `from` where the arrow starts, {x, y, z} in blocks; `eye` is the camera's eye, or nil when it is not known.
-- The game sends an arrow from the shooter's own position straight to the aimed point. With that point a block or two away (an
-- enemy at arm's length) the line is short and steep, and this arrow does not stop at the enemy: it flew on up, down or aside. So
-- a point nearer than aim_near blocks (on the ground plan) is pushed out to that distance along the camera's heading, at its own
-- height: the arrow leaves almost level, the way the player looks, and still passes the enemy. From aim_near on, and at that
-- distance exactly, the aim is the game's.
function M.arrow_direction(t, eye, aim, from)
  local ax, ay = aim.x - from.x, aim.y - from.y
  local near = math.sqrt(ax * ax + ay * ay)
  if near ~= near or near >= t.aim_near then return nil end
  local hx, hy, run = 0, 0, 0
  if eye then
    local ex, ey, ez = from.x - eye.x, from.y - eye.y, from.z - eye.z
    if math.sqrt(ex * ex + ey * ey + ez * ez) <= t.aim_eye_reach then          -- a camera farther off is not believed
      hx, hy = aim.x - eye.x, aim.y - eye.y
      run = math.sqrt(hx * hx + hy * hy)
    end
  end
  if run ~= run or run < t.aim_min_run then          -- no camera to go by, or it looks straight down: straight at the point
    hx, hy, run = ax, ay, near
    if run < t.aim_min_run then return nil end
  end
  local push = (t.aim_near - near) / run
  local dx, dy, dz = ax + hx * push, ay + hy * push, aim.z - from.z
  local len = math.sqrt(dx * dx + dy * dy + dz * dz)
  if len <= 0 then return nil end
  return dx / len, dy / len, dz / len
end

-- True once every `period_ms` while charging: `key` is the state's counter (ring_ms or sound_ms). The first call is due.
function M.due(state, key, dt_ms, period_ms)
  if not state.charging then return false end
  local left = state[key] - dt_ms
  if left <= 0 then
    state[key] = period_ms
    return true
  end
  state[key] = left
  return false
end

-- The sound of the charge at `charged` mp (the game's charged mp, 0 to 1), a name from t.charge_sounds: the charge is cut into as
-- many equal steps as there are sounds, the lowest at no charge. So the harp goes up the scale while mp is charged and holds its
-- note once the charge stops growing (at the player's mp), as the game's own sound holds its pitch (1 + 0.5 * charged mp).
-- Call it each time a sound is due.
function M.charge_sound(t, charged)
  local n = #t.charge_sounds
  local step = math.floor(M.charge_fraction(charged) * n) + 1
  if step > n then step = n end
  return t.charge_sounds[step]
end

-- The slow of the summoning: the player walked from `from` ({x, y}, where the last step left them) to x, y (blocks) in one
-- step; they keep only `factor` of that way. Returns the new x, y. Pulling them back along the way they came cannot put them
-- inside anything, whatever the game does with their speed.
function M.slowed(from, x, y, factor)
  return from.x + (x - from.x) * factor, from.y + (y - from.y) * factor
end

-- The ground direction across the player (to their left).
function M.across(facing) return { x = -facing.y, y = facing.x } end

-- ---- where the bow forms ---------------------------------------------------------------------------------------------------
-- A bow's frame is lib/grip's: { centre = {x, y, z} (the middle of the model's box, blocks), axes = { x, y, z } (the model's axes,
-- unit vectors), voxel = blocks, size = {x, y, z} voxels }. The model's z is its length; its string is at its y 0.

local function cross(a, b)
  local ax, ay, az = unpack(a)
  local bx, by, bz = unpack(b)
  return { ay * bz - az * by, az * bx - ax * bz, ax * by - ay * bx }
end

-- The model's length: its last axis and size.
local function length_of(frame)
  local _, _, long = unpack(frame.axes)
  local _, _, size = unpack(frame.size)
  return long, size
end

-- The frame when the player's draw record cannot be read (lib/grip gave nothing): the middle clasp_forward in front of the player
-- (`player` {x, y, z} blocks, `facing` the unit vector {x, y}) and clasp_height above, lying across them, the string on top (the
-- model's +y down), the voxel ghost_voxel. `size` is the model's.
function M.fallback_frame(t, player, facing, size)
  local a = M.across(facing)
  local long, down = { a.x, a.y, 0 }, { 0, 0, -1 }
  return { centre = { player.x + facing.x * t.clasp_forward, player.y + facing.y * t.clasp_forward, player.z + t.clasp_height },
    axes = { cross(down, long), down, long }, voxel = t.ghost_voxel, size = { unpack(size) } }
end

-- The bow's outline: `along` {x, y}, the ground direction of its length (across the player when it stands straight up), `across`
-- square to it, and the half sizes of its box seen from above (half_length along, half_depth across) and over its middle
-- (half_up). `facing` is the player's, for the upright case.
function M.bow_outline(frame, facing)
  local long = length_of(frame)
  local ax, ay = long[1], long[2]
  local flat = math.sqrt(ax * ax + ay * ay)
  if flat > 0 then
    ax, ay = ax / flat, ay / flat
  else
    local a = M.across(facing)
    ax, ay = a.x, a.y
  end
  local nx, ny = -ay, ax
  local half_length, half_depth, half_up = 0, 0, 0
  for i, b in ipairs(frame.axes) do
    local bx, by, bz = unpack(b)
    local h = frame.size[i] * frame.voxel / 2
    half_length = half_length + math.abs(bx * ax + by * ay) * h
    half_depth = half_depth + math.abs(bx * nx + by * ny) * h
    half_up = half_up + math.abs(bz) * h
  end
  return { along = { x = ax, y = ay }, across = { x = nx, y = ny }, half_length = half_length, half_depth = half_depth,
    half_up = half_up }
end

-- True while the summoning's motes are wanted in the air: from motes_from_ms of the summoning to its end.
function M.motes_on(t, state)
  return state.phase == M.SUMMON and state.summon_ms >= t.motes_from_ms
end

-- True once every motes_every_ms from motes_from_ms to motes_until_ms of the summoning (the first call in that time is due).
function M.motes_due(t, state, dt_ms)
  if not M.motes_on(t, state) or state.summon_ms >= t.motes_until_ms then return false end
  local left = state.motes_ms - dt_ms
  if left <= 0 then
    state.motes_ms = t.motes_every_ms
    return true
  end
  state.motes_ms = left
  return false
end

-- The rectangle the motes appear in, over the bow (`frame`): the bow's outline seen from above, motes_above over its top. Returns
-- its middle {x, y, z} (blocks), the ground direction of its length {x, y}, its length and its depth (blocks), as lib/fx's rect
-- takes them.
function M.motes_rect(t, frame, facing)
  local o = M.bow_outline(frame, facing)
  local x, y, z = unpack(frame.centre)
  return { x, y, z + o.half_up + t.motes_above }, { o.along.x, o.along.y }, 2 * o.half_length, 2 * o.half_depth
end

-- The steering rule of the motes for lib/fx: each drifts to its nearest point of the bow's middle line (the model's length through
-- the middle of its box, as long as the bow) and ends there, so they come down onto the whole bow. From the bow's top (half_up
-- over that line, and the mote's own half size) they shrink to nothing: they fade into the bow.
function M.motes_rule(t, frame, facing)
  local o = M.bow_outline(frame, facing)
  local long, size = length_of(frame)
  return { scale = t.motes.scale, target = { unpack(frame.centre) }, line = { unpack(long) },
    half = size * frame.voxel / 2, speed = t.motes_speed, reach = t.motes_reach, life_ms = t.motes_life_ms,
    fade = o.half_up + t.motes.scale / 2, levels = t.motes_fade_levels }
end

-- ---- the halo: the ring above the bow and its rays -----------------------------------------------------------------------------

local function ticks(ms) return math.ceil(ms / units.STEP_MS) end

-- The middle of the ring, {x, y, z} in blocks: halo_forward in front of the player (`player` {x, y, z}, `facing` {x, y}) and
-- halo_above over the bow's assumed height (clasp_height). Taken once, at the press: the halo stays there.
function M.halo_centre(t, player, facing)
  return { player.x + facing.x * t.halo_forward, player.y + facing.y * t.halo_forward,
    player.z + t.clasp_height + t.halo_above }
end

-- How far the rays go down from the ring: to halo_ray_below under the player's position.
function M.halo_drop(t) return t.clasp_height + t.halo_above + t.halo_ray_below end

-- The ring's inner radius at `age_ms` from the press (blocks).
function M.halo_inner(t, age_ms) return t.halo_inner + t.halo_grow * age_ms / units.MS_PER_S end

-- The fade after the take, for a shockwave or a beam: all of the opacity in halo_fade_ms, from its first tick.
local function fade_out(t, def)
  local n = ticks(t.halo_fade_ms)
  def.life_ticks, def.fade_on_tick, def.fade_speed = n, 0, 1 / n
  return def
end

-- The ring for lib/fx at `pos` (world units), flat, as it is `age_ms` after the press. `fading`: the fade after the take (a new
-- ring takes the old one's place at the same size), else it lives on until it is cancelled (halo_life_ms at most).
function M.halo_ring_def(t, pos, age_ms, fading)
  local def = { pos = pos, facing = { 0, 0, 1 }, inner = M.halo_inner(t, age_ms), thickness = t.halo_thickness,
    expansion = t.halo_grow * units.STEP_MS / units.MS_PER_S, life_ticks = ticks(t.halo_life_ms), fade_on_tick = 0,
    fade_speed = 0, color = t.halo_color }
  if fading then fade_out(t, def) end
  return def
end

-- Where ray `k` (1 to halo_rays) is `age_ms` after the press: from the middle of the ring's band round `centre` ({x, y, z},
-- blocks) down and outward to a circle of halo_ray_spread halo_drop lower, at an angle that turns halo_spin_deg_per_s. Returns
-- its start {x, y, z} (blocks), its direction (a unit vector) and its length (blocks). EMTweaks' cone_ray, with the ring's growth.
function M.halo_ray(t, centre, age_ms, k)
  local top = M.halo_inner(t, age_ms) + t.halo_thickness / 2
  local deg = t.halo_spin_deg_per_s * age_ms / units.MS_PER_S + units.FULL_TURN_DEG * (k - 1) / t.halo_rays
  local c, s = math.cos(math.rad(deg)), math.sin(math.rad(deg))
  local dx, dy, dz = (t.halo_ray_spread - top) * c, (t.halo_ray_spread - top) * s, -M.halo_drop(t)
  local len = math.sqrt(dx * dx + dy * dy + dz * dz)
  local cx, cy, cz = unpack(centre)
  return { cx + top * c, cy + top * s, cz }, { dx / len, dy / len, dz / len }, len
end

-- A ray for lib/fx: `pos` (world units), `dir` and `length` from halo_ray. `fading`: the fade after the take (it starts at full
-- opacity), else it rises in halo_ray_fade_in_ms and lives until it is cancelled.
function M.halo_ray_def(t, pos, dir, length, fading)
  local def = { pos = pos, dir = dir, length = length, radius_start = t.halo_ray_radius_start,
    radius_end = t.halo_ray_radius_end, color = t.halo_ray_color, edge_alpha = t.halo_ray_edge_alpha,
    pixel_size = t.halo_ray_pixel, fade_in_ticks = ticks(t.halo_ray_fade_in_ms), life_ticks = ticks(t.halo_life_ms),
    fade_on_tick = 0, fade_speed = 0 }
  if fading then
    def.fade_in_ticks = 0
    fade_out(t, def)
  end
  return def
end

-- The middle of the held bow, in blocks: where the charge's particles gather.
function M.bow_point(t, player, facing)
  return player.x + facing.x * t.bow_forward, player.y + facing.y * t.bow_forward, player.z + t.bow_height
end

-- The light the bow gives the frame (`glow.light_set`) at its point `at` ({x, y, z} in blocks): white, steady while it is held.
function M.bow_light(t, at)
  local r, g, b = unpack(t.light_color)
  local s = t.bow_light_power
  return { x = at.x, y = at.y, z = at.z, radius = t.bow_light_radius, r = r * s, g = g * s, b = b * s }
end

-- The light the player gives the frame (`glow.light_set`) at `centre`: full while the ability is on (left_ms = glow_ms), dimming
-- with what is left of glow_ms after it; nil when nothing is left.
function M.player_light(t, centre, left_ms)
  if not left_ms or left_ms <= 0 then return nil end
  local s = t.player_light_power * math.min(1, left_ms / t.glow_ms)
  local r, g, b = unpack(t.light_color)
  return { x = centre.x, y = centre.y, z = centre.z, radius = t.player_light_radius, r = r * s, g = g * s, b = b * s }
end

-- The release's ring for lib/fx, at `pos` (world units), its plane across the facing direction.
function M.wave_def(t, pos, facing)
  local grow = t.wave_radius - t.wave_inner - t.wave_thickness
  if grow < 0 then grow = 0 end
  return {
    pos = pos,
    facing = { facing.x, facing.y, 0 },
    inner = t.wave_inner,
    thickness = t.wave_thickness,
    expansion = grow / t.wave_ticks,
    life_ticks = t.wave_ticks,
    fade_on_tick = t.wave_fade_tick,
    fade_speed = t.wave_fade_speed,
    color = t.color,
  }
end

-- The points of the trail between two places of the arrow (`from` may be nil: the first step), {x, y, z} in blocks: one every
-- trail_spacing blocks back from `to`, at most trail_max_points, `to` itself first.
function M.trail_points(t, from, to)
  local out = { { x = to.x, y = to.y, z = to.z } }
  if from == nil then return out end
  local dx, dy, dz = from.x - to.x, from.y - to.y, from.z - to.z
  local len = math.sqrt(dx * dx + dy * dy + dz * dz)
  if len <= 0 then return out end
  local n = math.floor(len / t.trail_spacing)
  if n > t.trail_max_points - 1 then n = t.trail_max_points - 1 end
  for i = 1, n do
    local d = i * t.trail_spacing / len
    out[#out + 1] = { x = to.x + dx * d, y = to.y + dy * d, z = to.z + dz * d }
  end
  return out
end

-- The unit vector of the arrow's flight from `from` to `to` ({x, y, z} in blocks), or nil when it did not move.
function M.flight_dir(from, to)
  if from == nil then return nil end
  local dx, dy, dz = to.x - from.x, to.y - from.y, to.z - from.z
  local len = math.sqrt(dx * dx + dy * dy + dz * dz)
  if len <= 0 then return nil end
  return { x = dx / len, y = dy / len, z = dz / len }, len
end

-- The swirl's particles for one step of the arrow from `from` to `to`: a list of { pos = {x, y, z} blocks, vel = {x, y, z} blocks a
-- second } and the helix's phase after the step. A point lies every swirl_spacing back from `to`, on each strand; its push is
-- outward (round the line) and sideways, at the angle the helix has there. Nothing for a first step (`from` nil).
function M.swirl(t, from, to, phase)
  local d, len = M.flight_dir(from, to)
  if not d then return {}, phase end
  local ux, uy = d.y, -d.x                                -- d x up: square to the line, level
  local ul = math.sqrt(ux * ux + uy * uy)
  if ul <= 0 then ux, uy, ul = 1, 0, 1 end                -- a vertical line: any level direction
  ux, uy = ux / ul, uy / ul
  local vx, vy, vz = -d.z * uy, d.z * ux, d.x * uy - d.y * ux     -- d x u: the third axis
  local rate = t.swirl_turns_per_block * 2 * math.pi
  local after = phase + len * rate
  local n = math.floor(len / t.swirl_spacing)
  if n > t.swirl_max_points - 1 then n = t.swirl_max_points - 1 end
  local out = {}
  for j = 0, n do
    local back = j * t.swirl_spacing
    for k = 0, t.swirl_strands - 1 do
      local a = after - back * rate + k * 2 * math.pi / t.swirl_strands
      local c, s = math.cos(a), math.sin(a)
      local rx, ry, rz = c * ux + s * vx, c * uy + s * vy, s * vz            -- outward at angle a
      local tx, ty, tz = -s * ux + c * vx, -s * uy + c * vy, c * vz          -- round the line
      out[#out + 1] = {
        pos = { to.x - d.x * back, to.y - d.y * back, to.z - d.z * back },
        vel = { rx * t.swirl_out_speed + tx * t.swirl_spin_speed, ry * t.swirl_out_speed + ty * t.swirl_spin_speed,
          rz * t.swirl_out_speed + tz * t.swirl_spin_speed },
      }
    end
  end
  return out, after
end

-- The rule of the swirl's particles: a short life, and they slow down.
function M.swirl_rule(t)
  return { scale = t.swirl.scale, life_ms = t.swirl_life_ms, drag = t.swirl_drag }
end

-- The rule of the puff's particles: a short life, and they slow down.
function M.puff_rule(t)
  return { scale = t.puff.scale, life_ms = t.puff_life_ms, drag = t.puff_drag }
end

-- The pulse's ring for lib/fx, at `pos` (world units), its plane across the arrow's line `dir` ({x, y, z}).
function M.pulse_def(t, pos, dir)
  local grow = t.pulse_radius - t.pulse_inner - t.pulse_thickness
  if grow < 0 then grow = 0 end
  return {
    pos = pos,
    facing = { dir.x, dir.y, dir.z },
    inner = t.pulse_inner,
    thickness = t.pulse_thickness,
    expansion = grow / t.pulse_ticks,
    life_ticks = t.pulse_ticks,
    fade_on_tick = t.pulse_fade_tick,
    fade_speed = t.pulse_fade_speed,
    color = t.color,
  }
end

-- The steering rule of the charge's particles for lib/fx: they fly in to the bow's middle (blocks) and end there.
function M.charge_rule(t, x, y, z)
  return { scale = t.charge_particles.scale, target = { x, y, z }, speed = t.charge_speed, reach = t.charge_reach,
    life_ms = t.charge_life_ms }
end

-- The rule of the trail's particles: a short life.
function M.trail_rule(t)
  return { scale = t.trail.scale, life_ms = t.trail_life_ms }
end

-- A particle definition of the block (trail, puff, charge_particles) with the ability's colour, as a copy.
function M.particles(t, name)
  local d = {}
  for k, v in pairs(t[name]) do d[k] = v end
  d.color = t.color
  return d
end

-- The numbers of the skill tooltip at `rank`: two of the game's own placeholders used as carriers (see logic/guardian.lua): the
-- cooldown and the time with the bow, in seconds.
M.TOOLTIP_COOLDOWN, M.TOOLTIP_HOLD = "smashcooldown", "retreatdistance"

function M.tooltip_values(t, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(t, rank) / units.MS_PER_S),
    [M.TOOLTIP_HOLD] = ("%.0f"):format(t.hold_ms / units.MS_PER_S),
  }
end

-- ---- the server's arrow --------------------------------------------------------------------------------------------------------
-- The server's input is the client's own shoot packet: its start, its velocity and the charge the game spent. The server
-- checks it against its own copy of the player and computes the damage itself; the World's projectile step flies it.

local function ground_heading(x, y)
  local len = math.sqrt(x * x + y * y)
  if len <= 0 or len ~= len then return nil end
  return x / len, y / len, len
end

-- Checks one shot. `s` = { held = the bow is held (phase HELD), bow = the server's copy holds the marked bow, from = the packet's
-- start, at = the server's copy's position, vel = the packet's velocity, aim = the server's copy's aim point (or nil) }, all
-- {x, y, z} in blocks. Returns true, or false and the reason.
function M.check_shot(t, s)
  if not s.held then return false, "the bow is not held" end
  if not s.bow then return false, "the server's copy holds no bow of light" end
  local dx, dy, dz = s.from.x - s.at.x, s.from.y - s.at.y, s.from.z - s.at.z
  local off = math.sqrt(dx * dx + dy * dy + dz * dz)
  if not (off <= t.shot_range_slack) then return false, ("the start is %.1f blocks from the player"):format(off) end
  local hx, hy = ground_heading(s.vel.x, s.vel.y)
  local speed = math.sqrt(s.vel.x * s.vel.x + s.vel.y * s.vel.y + s.vel.z * s.vel.z)
  if not (speed > 0) then return false, "the shot does not move" end
  if s.aim and hx then
    local ax, ay, len = ground_heading(s.aim.x - s.from.x, s.aim.y - s.from.y)
    if ax and len >= t.shot_cone_min then
      local dot = math.max(-1, math.min(1, hx * ax + hy * ay))
      local deg = math.deg(math.acos(dot))
      if deg > t.shot_cone_deg then return false, ("the heading is %.0f degrees off the aim"):format(deg) end
    end
  end
  return true
end

return M
end

-- @module skills_unleashed.logic.water_mage (logic/water_mage.lua)
package.preload["skills_unleashed.logic.water_mage"] = function(...)
-- skills_unleashed.logic.water_mage: the rules of the Water Mage's Chain of the Deep. Pure: no kyubu, no
-- ffi, so a unit test decides it. Every number is in lib/tuning.lua (`water_mage`).
--
-- A pulse is a table: id, x, y, z (blocks: the mage's feet where it was cast), age (ms since the cast), rank, caught (creature id ->
-- true: every enemy the ring has reached, snared or not, so a creature that is reached is judged once), snared (how many were
-- snared), sounds (how many chains sounds it has queued, catch_sound_max at most), sound_due (the ages, ms, at which the queued ones
-- play, in order) and last_sound (the age the last one played at). The ring grows by the same clock as EMTweaks' pulse (radius), and an enemy is
-- caught when the ring reaches the edge of its body: the distance on the ground minus its half width is within the radius.
local tuning = require("skills_unleashed.lib.tuning")
local units = require("skills_unleashed.lib.units")

local M = {}

M.MARKER_CAST = "cast"      -- the player's clip: the hands are flung out, the pulse leaves the feet

function M.new_state() return { pulses = {}, next_id = 1 } end

-- The length of the snare at `rank` in ms: the first rank's, and the points lengthen it as the game's own strength saturates.
function M.snare_ms(T, rank)
  local i = rank
  if i < 1 then i = 1 end
  return T.snare_ms + T.snare_gain_ms * tuning.power(i - 1, T.rank_scale)
end

-- How long the ring takes to reach its radius, ms.
function M.travel_ms(T) return T.pulse_ticks * T.tick_ms end

-- The ring's radius `age_ms` after the cast, blocks (EMTweaks' own line: from pulse_start to pulse_radius in pulse_ticks).
function M.radius(T, age_ms)
  local travel = M.travel_ms(T)
  local a = age_ms
  if a < 0 then a = 0 end
  if a > travel then a = travel end
  return T.pulse_start + (T.pulse_radius - T.pulse_start) * a / travel
end

-- A new pulse cast by a mage whose feet are at `feet` {x, y, z} (blocks), at `rank`. Not in the state yet (add does that).
function M.new_pulse(state, feet, rank)
  local id = state.next_id
  state.next_id = id + 1
  return { id = id, x = feet.x, y = feet.y, z = feet.z, age = 0, rank = rank, caught = {}, snared = 0, sounds = 0,
    sound_due = {}, last_sound = nil }
end

function M.add(state, pulse) state.pulses[#state.pulses + 1] = pulse end

function M.remove(state, pulse)
  for i, p in ipairs(state.pulses) do
    if p == pulse then table.remove(state.pulses, i); return true end
  end
  return false
end

-- The EMTweaks pulse for this one (fx.pulse takes it with pos in world units; here in blocks).
function M.pulse_def(T, pulse)
  return {
    pos = { pulse.x, pulse.y, pulse.z + T.pulse_lift },
    radius = T.pulse_radius, radius_start = T.pulse_start, travel_ticks = T.pulse_ticks, seed = pulse.id,
  }
end

-- One step of a pulse (dt in ms): it ages, and every enemy (lib/combat.read tables) that the ring reaches now and that it has not
-- reached before is caught. `can_snare(id)` says whether the snare takes it (not snared, not immune). Returns { entries, done }:
-- the entries newly caught, nearest first, each { c = the enemy, d = ground distance, snare = bool }, and whether the ring has
-- run out.
function M.step(T, pulse, dt_ms, enemies, can_snare)
  pulse.age = pulse.age + dt_ms
  local r = M.radius(T, pulse.age)
  local out = {}
  for _, e in ipairs(enemies) do
    if not pulse.caught[e.id] then
      local dx, dy = e.x - pulse.x, e.y - pulse.y
      local d = math.sqrt(dx * dx + dy * dy)
      local up = (e.feet or e.z) - pulse.z
      if d - (e.half_width or 0) <= r and math.abs(up) <= T.reach_z then
        pulse.caught[e.id] = true
        out[#out + 1] = { c = e, d = d, snare = can_snare(e.id) and true or false }
      end
    end
  end
  table.sort(out, function(p, q)
    if p.d ~= q.d then return p.d < q.d end
    return (p.c.id or 0) < (q.c.id or 0)
  end)
  return out, pulse.age >= M.travel_ms(T)
end

-- Queues a chains sound for each of `n` creatures snared now, while the pulse has had fewer than catch_sound_max: the first at
-- once, each next one catch_sound_gap_ms after the one before (so several snared in one step are each heard).
function M.queue_sounds(T, pulse, n)
  for _ = 1, n do
    if pulse.sounds >= T.catch_sound_max then return end
    pulse.sounds = pulse.sounds + 1
    local due = pulse.age
    local last = pulse.sound_due[#pulse.sound_due] or pulse.last_sound
    if last and due < last + T.catch_sound_gap_ms then due = last + T.catch_sound_gap_ms end
    pulse.sound_due[#pulse.sound_due + 1] = due
  end
end

-- How many queued chains sounds are due at the pulse's age now; they leave the queue.
function M.due_sounds(pulse)
  local n = 0
  while pulse.sound_due[1] and pulse.sound_due[1] <= pulse.age do
    pulse.last_sound = table.remove(pulse.sound_due, 1)
    n = n + 1
  end
  return n
end

-- Whether the pulse is over: its ring has run out (`ring_done`, from step) and no chains sound waits.
function M.over(pulse, ring_done) return ring_done and #pulse.sound_due == 0 end

-- The chains round a creature (an fx.chains def, pos in blocks): its feet, its size from its hitbox (the size is capped at what
-- EMTweaks takes), seeded by its id so every client would draw the same set.
function M.chains_def(T, e)
  local radius = math.min(e.half_width or 0, T.chains_max_radius)
  local height = math.min(((e.z - (e.feet or e.z))) * 2, T.chains_max_height)
  local def = { pos = { e.x, e.y, e.feet or e.z }, seed = e.id % units.BLOCK }
  if radius > 0 then def.target_radius = radius end
  if height > 0 then def.target_height = height end
  -- one voxel count for every size: the voxel is as big as the creature needs for its radius and height to be no more than the
  -- pinned counts (bigger cubes for a bigger creature); none for a creature of no size (EMTweaks' own default, with its own voxel)
  local voxel = math.max(radius / T.chains_voxel_radius, height / T.chains_voxel_height)
  if voxel > 0 then def.voxel_size = math.min(voxel, T.chains_voxel_max) end
  return def
end

-- The skill tooltip's placeholders at `rank` (assets/text/dict_en.xml, AbilityChainOfTheDeep): the cooldown and the snare in seconds.
M.TOOLTIP_COOLDOWN = "smashcooldown"
M.TOOLTIP_SNARE = "retreatdistance"
function M.tooltip_values(T, rank)
  return {
    [M.TOOLTIP_COOLDOWN] = ("%.0f"):format(tuning.cooldown_at(T, rank) / units.MS_PER_S),
    [M.TOOLTIP_SNARE] = ("%.1f"):format(M.snare_ms(T, rank) / units.MS_PER_S),
  }
end

return M
end

